function _zoneName(id) {
  if (id == null) return null;
  const n = Number(id);
  return ZONE_NAMES[n] || null;
}
// Live pet (Zeal gauge slot 16) keyed by lowercase character = the pet's owner.
// Only the local uploader's own character streams gauges, so this resolves the
// uploader's pet HP/name — used by both _serializeZealForWeb (Buffs & Zone pet
// line) and the /api/state charmPets array (charm overlay). Read at call time,
// so it's safe to invoke from the request handler defined earlier in the file.
function _livePetHpByOwner() {
  const out = new Map();
  for (const ch of Object.keys(_zealState)) {
    const st = _zealState[ch];
    if (!st || !Array.isArray(st.gauges)) continue;
    const pet = st.gauges.find(g => g && g.slot === 16 && g.text);
    if (pet) out.set(String(ch).toLowerCase(), { name: pet.text, hp_pct: pet.hp_pct });
  }
  return out;
}

// ── Mob Info (target NPC stats) for the Mimic overlay ────────────────────────
// The agent's current Zeal target → eqemu_npc_types stats, fetched once per mob
// from the bot's /api/agent/mob-info and cached (static catalog data). Exposed
// on /api/state as `mobInfo` with the live target HP% layered on; the overlay
// renders HP / AC / resists / special attacks.
const _mobInfoByName  = new Map();   // normName → { at, mob|null }
const _mobInfoInflight = new Set();
const MOB_INFO_TTL_MS = 6 * 60 * 60 * 1000;
function _normMobNameAgent(n) {
  // Strip the "'s corpse" suffix so the Mob Info cache key matches the live
  // NPC row for a freshly-killed mob you're looting from. Without this,
  // Vyzh`dra's corpse normalizes to vyzh_dra_the_exiled_s_corpse and the
  // bot's catalog lookup never hits the actual npc_types row.
  return String(n || '').trim().toLowerCase()
    .replace(/'s\s+corpse$/, '')
    .replace(/[\s`'’]+/g, '_').replace(/^#/, '');
}
// #141 — cache key carries the requester's zone id so a same-name mob in
// ANOTHER zone re-resolves instead of serving a stale cross-zone catalog row.
function _mobInfoCacheKey(name, zoneId) {
  return _normMobNameAgent(name) + '|' + (zoneId != null ? zoneId : '*');
}
function fetchMobInfo(name, selfChar, zoneId) {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;          // local-only → no lookup
  const norm = _normMobNameAgent(name);
  if (!norm) return;
  const key = _mobInfoCacheKey(name, zoneId);
  if (_mobInfoInflight.has(key)) return;
  const cached = _mobInfoByName.get(key);
  if (cached && (Date.now() - cached.at) < MOB_INFO_TTL_MS) return;
  _mobInfoInflight.add(key);
  // #141 — send the requesting character so the bot zone-scopes the catalog row
  // (id = zoneid*1000+n) to OUR zone; absent → bot falls back catalog-wide.
  let url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/mob-info') + '?name=' + encodeURIComponent(name);
  if (selfChar) url += '&character=' + encodeURIComponent(selfChar);
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 8000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _mobInfoInflight.delete(key);
        try { const j = JSON.parse(body); _mobInfoByName.set(key, { at: Date.now(), mob: (j && j.mob) ? j.mob : null }); }
        catch { _mobInfoByName.set(key, { at: Date.now(), mob: null }); }
      });
    });
    req.on('error',   () => { _mobInfoInflight.delete(key); });
    req.on('timeout', () => { req.destroy(); _mobInfoInflight.delete(key); });
    req.end();
  } catch { _mobInfoInflight.delete(key); }
}
// Cast time (seconds) for a spell from the catalog (cast_ms). Default 4s when
// the catalog doesn't carry it — a "You begin casting" line implies a real cast.
function _spellCastSecs(name) {
  const e = _spellByNameLower.get(String(name || '').toLowerCase());
  const ms = (e && e.cast_ms != null) ? Number(e.cast_ms) : null;
  return (ms != null && ms >= 0) ? Math.round(ms / 100) / 10 : 4;
}
// Cross-client casts on the current target — fetched from the bot's relay with a
// short TTL so the Mob Info "Casting" section stays near-real-time without
// hammering the endpoint. Cached per normalized target name.
const _targetCastsByName  = new Map();   // relayKey → { at, casts }
const _targetCastsInflight = new Set();
const TARGET_CASTS_TTL_MS = 2000;
// #141 — the cross-client relay cache is keyed by (target, requester) so the
// zone-scoped Mob Info fetch (passes selfChar → bot filters to our zone) never
// collides with an unscoped caller for the same target name.
// ⚠ targetId is part of the key, not just the query. Without it, swapping
// between two same-name mobs reuses the first one's cached relay answer and the
// bot-side filtering is undone on the way back in.
function _relayCacheKey(name, selfChar, targetId) {
  return String(name || '').trim().toLowerCase() + '|' + String(selfChar || '').trim().toLowerCase()
       + (targetId != null ? '|' + targetId : '');
}
function fetchTargetCasts(name, selfChar, targetId) {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;
  if (!String(name || '').trim()) return;
  const key = _relayCacheKey(name, selfChar, targetId);
  if (_targetCastsInflight.has(key)) return;
  const cached = _targetCastsByName.get(key);
  if (cached && (Date.now() - cached.at) < TARGET_CASTS_TTL_MS) return;
  _targetCastsInflight.add(key);
  let url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/target-casts') + '?name=' + encodeURIComponent(name);
  if (selfChar) url += '&character=' + encodeURIComponent(selfChar);   // #141 zone scope
  // Spawn id first, name second — the bot drops casts proven to be on a
  // different same-name spawn. Omitted when unknown → served unfiltered.
  if (targetId != null) url += '&target_id=' + encodeURIComponent(targetId);
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 6000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _targetCastsInflight.delete(key);
        try { const j = JSON.parse(body); _targetCastsByName.set(key, { at: Date.now(), casts: (j && j.casts) || [] }); }
        catch { _targetCastsByName.set(key, { at: Date.now(), casts: [] }); }
      });
    });
    req.on('error',   () => { _targetCastsInflight.delete(key); });
    req.on('timeout', () => { req.destroy(); _targetCastsInflight.delete(key); });
    req.end();
  } catch { _targetCastsInflight.delete(key); }
}

// Cross-client target_buffs on the current target — pulled from buff_casts via
// the bot's /api/agent/target-buffs relay. Same shape as target_casts: short
// TTL, per-target cache, lazy-fetched from buildMobInfo. Lets us see e.g. who
// is charming the same mob we're targeting, and any tracked buff anyone has
// landed on it. Merged with the LOCAL _buffLandingsByTarget for display.
const _targetBuffsByName  = new Map();   // nameLower → { at, buffs }
const _targetBuffsInflight = new Set();
// 12s — long enough that a roomful of Mimics doesn't multiplicatively hammer
// the bot's /target-buffs relay (the same query firing every 2-3s across
// every client visiting the same target was Supabase egress culprit #1).
// Target Info still feels live: 12s of cross-client buff visibility is fine
// for the "did anyone else just land Tash on this mob" question.
// Mob Info target-buffs cache TTL. Default 12s (was 5s pre-egress
// triage — a roomful of Mimics on the same target was fan-out hot). Dial
// down for tighter freshness on a fat-egress tier, up for a tight one.
// 2026-06-21: cranked default 12s → 6s after the Supabase Pro upgrade.
// Original was 5s; 6s splits the difference so Mob Info feels live again
// without the full pre-squeeze churn. Override via WP_TARGET_BUFFS_TTL_MS.
const TARGET_BUFFS_TTL_MS = parseInt(process.env.WP_TARGET_BUFFS_TTL_MS, 10) || 6000;
function fetchTargetBuffs(name, selfChar, targetId) {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;
  if (!String(name || '').trim()) return;
  const key = _relayCacheKey(name, selfChar, targetId);   // #141 (target, requester) + spawn
  if (_targetBuffsInflight.has(key)) return;
  const cached = _targetBuffsByName.get(key);
  if (cached && (Date.now() - cached.at) < TARGET_BUFFS_TTL_MS) return;
  _targetBuffsInflight.add(key);
  let url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/target-buffs') + '?name=' + encodeURIComponent(name);
  if (selfChar) url += '&character=' + encodeURIComponent(selfChar);   // #141 zone scope
  // Lets the bot drop rows proven to belong to a different same-name spawn.
  // Omitted when unknown → the bot serves unfiltered, exactly as before.
  if (targetId != null) url += '&target_id=' + encodeURIComponent(targetId);
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 6000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _targetBuffsInflight.delete(key);
        try { const j = JSON.parse(body); _targetBuffsByName.set(key, { at: Date.now(), buffs: (j && j.buffs) || [] }); }
        catch { _targetBuffsByName.set(key, { at: Date.now(), buffs: [] }); }
      });
    });
    req.on('error',   () => { _targetBuffsInflight.delete(key); });
    req.on('timeout', () => { req.destroy(); _targetBuffsInflight.delete(key); });
    req.end();
  } catch { _targetBuffsInflight.delete(key); }
}

// Main-Tank live state — the MT's OWN Mimic's uploaded Zeal snapshot (full
// buff list + HP), via the bot's /api/agent/character-live-state relay.
// Authoritative when the MT runs Mimic: their agent re-sends on any buff-set
// change (20s heartbeat while targeting), so this beats observed-landing
// inference, which never sees worn clickies or pre-fight buffs. Same lazy
// cache/inflight pattern as fetchTargetBuffs; 8s TTL keeps a roomful of
// Mimics from stacking Supabase reads while the overlay still feels live.
// ── DI status poll (BACKLOG §1) ──────────────────────────────────────────────
// Per-cleric Divine Intervention readiness from the bot (aggregated across
// every Mimic cleric's live-state di_ready_at). Cached ~4s; the CH-chain +
// Command Center overlays read it off /api/state / /api/command-center. Our
// OWN clerics' state is merged from _diStateByChar at serialize time so the
// local view never waits on the round trip.
let _diStatusCache = { at: 0, clerics: [], healer_mana: [] };
let _diStatusInflight = false;
const DI_STATUS_TTL_MS = 4000;
function fetchDiStatus() {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;
  if (_diStatusInflight || (Date.now() - _diStatusCache.at) < DI_STATUS_TTL_MS) return;
  _diStatusInflight = true;
  const url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/di-status');
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 6000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _diStatusInflight = false;
        try {
          const j = JSON.parse(body);
          _diStatusCache = {
            at: Date.now(),
            clerics: Array.isArray(j && j.clerics) ? j.clerics : [],
            // Piggybacked Mimic healers' exact mana (bot 3.0.187+) — feeds
            // the Command Center HEALER MANA merge.
            healer_mana: Array.isArray(j && j.healer_mana) ? j.healer_mana : [],
          };
        } catch { _diStatusCache = { at: Date.now(), clerics: _diStatusCache.clerics, healer_mana: _diStatusCache.healer_mana || [] }; }
      });
    });
    req.on('error',   () => { _diStatusInflight = false; });
    req.on('timeout', () => { req.destroy(); _diStatusInflight = false; });
    req.end();
  } catch { _diStatusInflight = false; }
}
// Snapshot for overlays: bot list ⊕ local override (our own machine's DI
// stamps are authoritative + latency-free for characters we watch).
function diStatusSnapshot() {
  fetchDiStatus();
  const now = Date.now();
  const byName = new Map();
  for (const c of (_diStatusCache.clerics || [])) {
    if (!c || !c.name) continue;
    const readyMs = c.ready_at ? Date.parse(c.ready_at) : null;
    byName.set(String(c.name).toLowerCase(), {
      name: c.name,
      ready_at_ms: readyMs,
      // `up` stays assumed-ready for consumers that gate on it, but UNKNOWN is
      // now distinguishable. A null ready_at does not mean the DI is available
      // — it means we never SAW the cast. Fargan showed a green tick while his
      // DI was on cooldown, purely because nobody's log gave us his cast
      // (Hitya 2026-08-06, and it is NOT clock skew: the measured offsets
      // are +314ms / +210ms, and Fargan has no offset row at all).
      up: readyMs == null || readyMs <= now,
      unknown: readyMs == null,
      seconds: readyMs != null && readyMs > now ? Math.ceil((readyMs - now) / 1000) : 0,
    });
  }
  for (const [cl, di] of _diStateByChar) {
    // Resolve the display-cased name from our watched characters; a name
    // unknown to both the local watch AND the bot list is skipped.
    let display = null;
    for (const ch of Object.keys(_zealState || {})) if (String(ch).toLowerCase() === cl) display = ch;
    if (!display && !byName.has(cl)) continue;
    const name = display || byName.get(cl).name;
    byName.set(cl, {
      name,
      ready_at_ms: di.readyAt,
      up: di.readyAt <= now,
      unknown: false,          // we watched this cast ourselves
      seconds: di.readyAt > now ? Math.ceil((di.readyAt - now) / 1000) : 0,
    });
  }
  // Drop assumed-ready clerics who aren't actually in the raid. The default-
  // ready rule (a cleric who hasn't cast DI shows "up") over-includes a parked
  // / boxed cleric alt that doesn't even have DI scribed (Hitya's Manamana,
  // 2026-07-16). Keep anyone who has genuinely cast DI recently (seconds > 0 =
  // on cooldown = definitely has the spell) and anyone present in the live raid
  // roster; only prune when we actually have a fresh, populated roster to judge
  // against (else fall back to showing everyone — better than hiding a real DI).
  let list = [...byName.values()];
  const _raidFresh = _lastRaidPipe && Array.isArray(_lastRaidPipe.members) &&
                     (Date.now() - (_lastRaidPipe.at || 0)) < 10 * 60 * 1000;
  if (_raidFresh) {
    const raidNames = new Set(_lastRaidPipe.members
      .map(m => (m && m.name) ? String(m.name).toLowerCase() : null).filter(Boolean));
    if (raidNames.size >= 8) {
      list = list.filter(c => c.seconds > 0 || raidNames.has(String(c.name).toLowerCase()));
    }
  }
  list.sort((a, b) => (a.up === b.up ? a.name.localeCompare(b.name) : a.up ? -1 : 1));
  return { clerics: list, up_count: list.filter(c => c.up).length };
}
// 8s felt sluggish once cross-client tank HP shipped (a non-local MT's bar only
// refreshed every ~8s on top of the roster/relay lag). 2.5s keeps the Tank bar
// live; reads dedup through the bot's own relay cache so a roomful of Mimics
// doesn't multiply Supabase load. Tunable via WP_MT_LIVE_STATE_TTL_MS.
const MT_LIVE_STATE_TTL_MS = parseInt(process.env.WP_MT_LIVE_STATE_TTL_MS, 10) || 2500;
// Cross-client live-state cache + in-flight de-dupe. These back EVERY cross-
// client HP/buff lookup (_resolveHpValuesForName, _resolveBuffsForName,
// buildMobInfo) but their declarations had gone missing, so every non-self
// target lookup threw "ReferenceError: _mtLiveStateByName is not defined". That
// silently killed cross-client tank HP (tank stuck on "[local]"), and — once
// the 3.3.71 buff-filter fix stopped masking it — hard-blanked the Tank +
// Command Center overlays and stopped Mob Info switching to players/pets
// (raid-night 2026-07-16). Restore them here, next to the fetch that fills them.
const _mtLiveStateByName   = new Map();   // nameLower → { at, state } (bot-relayed Zeal snapshot)
const _mtLiveStateInflight = new Set();   // nameLower currently being fetched
function fetchCharacterLiveState(name) {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;
  const key = String(name || '').trim().toLowerCase();
  if (!key || _mtLiveStateInflight.has(key)) return;
  const cached = _mtLiveStateByName.get(key);
  if (cached && (Date.now() - cached.at) < MT_LIVE_STATE_TTL_MS) return;
  _mtLiveStateInflight.add(key);
  const url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/character-live-state') + '?name=' + encodeURIComponent(name);
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 6000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _mtLiveStateInflight.delete(key);
        try { const j = JSON.parse(body); _mtLiveStateByName.set(key, { at: Date.now(), state: (j && j.state) || null }); }
        catch { _mtLiveStateByName.set(key, { at: Date.now(), state: null }); }
      });
    });
    req.on('error',   () => { _mtLiveStateInflight.delete(key); });
    req.on('timeout', () => { req.destroy(); _mtLiveStateInflight.delete(key); });
    req.end();
  } catch { _mtLiveStateInflight.delete(key); }
}

// Buff queue cache (per buffer-class). Mimic's buff-queue overlay polls the
// local agent which proxies to the bot's /api/agent/raid-buff-queue. The TTL is
// tuned so a roomful of Mimics doesn't hammer Supabase but the overlay still
// feels live (~3-5s between full refreshes).
const _buffQueueCache = new Map();   // classLower|character → { at, payload }
const _buffQueueInflight = new Set();
// "Buffs feel laggy" snappy mode — when the user clicks the lag-report button
// in the overlay we drop the effective cache TTL to 500ms for 60s so the next
// dozen overlay ticks (at 1.5s) get fresh data. The local agent is the only
// gating layer between the overlay's 1.5s loop and the bot's Supabase query,
// so flipping this alone is enough to make the queue feel snappy without any
// overlay-side change.
let _buffQueueSnappyUntil = 0;
const SNAPPY_TTL_MS  = 500;
const SNAPPY_WINDOW  = 60_000;
// Raid-buff-queue cache TTL on the agent. History: 3s pre-egress-squeeze →
// 8s during the squeeze → 4s after the 2026-06-21 Supabase Pro upgrade gave
// back headroom → 2s on 2026-07-03 (Hitya: "Debuff queue definitely needs
// to be faster") — the bigger win there was flushLiveStateToBot's own
// interval (20s → 5s, see main()), which gates whether the bot even KNOWS
// about a new debuff before this cache's freshness matters at all; this TTL
// just trims the remaining read-side lag on top of that. The overlay polls
// every 1.5s, so 2s still means most ticks reuse the cache rather than
// re-fetching every single one. Override via WP_BUFF_QUEUE_TTL_MS.
const BUFF_QUEUE_TTL_MS = parseInt(process.env.WP_BUFF_QUEUE_TTL_MS, 10) || 2000;
function fetchRaidBuffQueue(bufferClass, bufferCharacter) {
  const opts = _uploadOpts;
  if (!opts || !opts.botUrl || !opts.token) return;
  const key = String(bufferClass || '').trim().toLowerCase() + '|' + String(bufferCharacter || '').trim().toLowerCase();
  if (_buffQueueInflight.has(key)) return;
  const cached = _buffQueueCache.get(key);
  const ttl = (Date.now() < _buffQueueSnappyUntil) ? SNAPPY_TTL_MS : BUFF_QUEUE_TTL_MS;
  if (cached && (Date.now() - cached.at) < ttl) return;
  _buffQueueInflight.add(key);
  const qs = [];
  if (bufferClass)     qs.push('class=' + encodeURIComponent(bufferClass));
  if (bufferCharacter) qs.push('character=' + encodeURIComponent(bufferCharacter));
  const url = opts.botUrl.replace(/\/encounter(\?.*)?$/, '/raid-buff-queue') + (qs.length ? '?' + qs.join('&') : '');
  try {
    const u = new URL(url);
    const mod = u.protocol === 'https:' ? https : http;
    const req = mod.request({
      method: 'GET', hostname: u.hostname, port: u.port, path: u.pathname + u.search,
      headers: { 'Authorization': 'Bearer ' + opts.token, 'User-Agent': `wolfpack-logsync/${AGENT_VERSION}` },
      timeout: 8000,
    }, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        _buffQueueInflight.delete(key);
        try { const j = JSON.parse(body); _buffQueueCache.set(key, { at: Date.now(), payload: j }); }
        catch { _buffQueueCache.set(key, { at: Date.now(), payload: { buff_queue: [], debuff_queue: [] } }); }
      });
    });
    req.on('error',   () => { _buffQueueInflight.delete(key); });
    req.on('timeout', () => { req.destroy(); _buffQueueInflight.delete(key); });
    req.end();
  } catch { _buffQueueInflight.delete(key); }
}

// ── PoP raid objectives proxy (popraid.html) ─────────────────────────────────
// The PoP overlay polls the local agent's /api/pop-objectives; we proxy the
