const AOE_DANCE = [
  {
    boss:            'Vyzh`dra the Cursed',
    spell:           'Dragon Roar',                   // eqemu_spells 789/981 — fear PBAE (targettype 4), MR-based
    signature:       [/You lose control of yourself!/i,       // self-land (the fear)
                      /You resist the Dragon Roar spell!/i],  // resist — still proves the AE fired
    burst_n:         1,                               // self-only evidence (cast_on_other NULL) — see note above
    burst_window_ms: 2000,                            // echo/alt-log dupe absorber
    cadence_sec:     36,                              // FIELD-TUNABLE — spell recast_time 36000ms; confirm on next kill
    out_warn_sec:    5,                               // speak "MELEE OUT" this many seconds before the next AE
    out_text:        'MELEE OUT — Dragon Roar soon',  // countdown warning callout (the pre-warn)
    in_text:         'MELEE IN',                      // fired NOW when the AE lands (safe to re-engage)
    color:           'gold',
  },
  {
    // #182 — GROUNDED SIGNATURE — Ancient Breath, eqemu_spells 1486, on Vulak`Aerr
    // (npc_types 124128 "#Vulak`Aerr", npc_spells_id 1204, entry recast_delay -1):
    //   • cast_time 0 → no cast message; effect-detection only (like Caustic Mist).
    //   • cast_on_other is NULL → bystanders see NOTHING. The ONLY evidence is your
    //     own land line, so burst_n is 1 — one self-land = the AE fired (the
    //     burst_window_ms quiet window still absorbs alt-log echoes).
    //   • land-on-self: "Your life force drains away." (shared only with the Life
    //     Curse / Dark Siphon lifetaps + unused placeholders — the active-boss gate
    //     scopes it to this fight; a stray tap just re-syncs the countdown early).
    //   • cadence: spell recast_time 60000ms, npc entry defers (-1) → 60s default,
    //     FIELD-TUNABLE; re-syncs on every land you eat.
    //   • out_warn_sec 4 per Hitya 2026-07-24: "calling DPS OUT at 4 seconds
    //     beforehand".
    boss:            'Vulak`Aerr',
    spell:           'Ancient Breath',                // eqemu_spells 1486 — PBAE (targettype 4), disease -150
    signature:       [/Your life force drains away\./i], // land-on-self ONLY (cast_on_other NULL)
    burst_n:         1,                               // one self-land = the AE fired (see note above)
    burst_window_ms: 2000,                            // echo/alt-log dupe absorber
    cadence_sec:     60,                              // FIELD-TUNABLE — spell recast_time 60000ms
    out_warn_sec:    4,                               // speak "DPS OUT" 4s before the predicted next AE
    out_text:        'DPS OUT — Ancient Breath soon',
    in_text:         'DPS IN',
    color:           'gold',
  },
];
// One burst = one fire. Keyed per boss so a whole burst of land lines (and any
// cross-log echo) collapses to a single fire — the #36 analogue of _busterLastFire.
const _aoeDanceLastFire = new Map();   // boss(lc) → wall-clock ms of the last fire
const _aoeDanceBurst    = new Map();   // boss(lc) → { count, windowStartMs } rolling collector

// A signature land line → count it toward the active burst; once >= burst_n
// land within burst_window_ms, treat the AE as fired: push the entry's in_text
// ("MELEE IN"/"DPS IN") NOW and (re)arm the countdown to the NEXT AE (target =
// boss so death clears it, like the buster) whose warning at out_warn_sec
// speaks the entry's out_text pre-warn.
// GATED on the boss being the ACTIVE encounter (curBoss, same pattern as
// _checkTankBuster) so an identically-worded land line on trash elsewhere can't
// fire it. Local only — every raider's own log carries the land burst.
function _checkAoeDance(line, tsMs) {
  if (!line) return;
  const curBoss = (stats.currentEncounterThreat && stats.currentEncounterThreat.bossName)
    ? String(stats.currentEncounterThreat.bossName).toLowerCase() : null;
  if (!curBoss) return;                                       // no active fight → never fire
  const now = tsMs || Date.now();
  for (const d of AOE_DANCE) {
    if (curBoss !== d.boss.toLowerCase()) continue;           // only THIS dance boss, and only while it's active
    if (!d.signature.some(rx => rx.test(line))) continue;     // not this AE's land text
    const key = d.boss.toLowerCase();
    // Post-fire quiet window: once we've fired for a burst, ignore the rest of
    // the same burst's land lines (and cross-log echoes) for burst_window_ms —
    // "one burst = one fire across the burst window" (echo guard).
    if (now - (_aoeDanceLastFire.get(key) || 0) < d.burst_window_ms) return;
    // Roll a fresh window if the previous collector is stale (>burst_window_ms
    // old), else accumulate this victim into it.
    let b = _aoeDanceBurst.get(key);
    if (!b || (now - b.windowStartMs) > d.burst_window_ms) {
      b = { count: 0, windowStartMs: now };
      _aoeDanceBurst.set(key, b);
    }
    b.count++;
    if (b.count < d.burst_n) return;                          // not a burst yet — a single stray line never fires
    // Burst confirmed — the AE just went off.
    _aoeDanceLastFire.set(key, now);
    _aoeDanceBurst.delete(key);
    _armBossCountdown({
      boss: d.boss, label: d.spell, durationSec: d.cadence_sec,
      warnSec: d.out_warn_sec, warnText: d.out_text,
      fireText: d.in_text, color: d.color || 'gold', tsMs: now,
    });
    console.log('[aoe-dance] ' + d.spell + ' on ' + d.boss + ' — ' + d.in_text + ' + re-armed ' + d.cadence_sec + 's countdown');
    return;
  }
}
// ── #207 callout dismissals — the implicit signal ───────────────────────────
// Hitya 2026-08-03: "those lines should be dismissable AND we should track when
// things are dismissed so we learn from items that people either don't care
// about or may be inaccurate" (docs/DESIGN-callout-overlay.md §3.2).
//
// Two directions ride the EXISTING trigger_timing_feedback stream rather than a
// new table:
//   • `dismissed` — the raider cleared the row. The most honest signal we can
//     collect, and it costs them nothing extra: they were already swatting it
//     away. Compare the explicit thumbs-up widget — 47 votes from 7 people in a
//     month, because pressing a feedback button mid-raid competes with playing.
//   • `expired`   — the row aged out untouched. This is the CONTROL GROUP, and
//     it is what makes the signal readable at all: 3 dismissals is damning at 3
//     fires and meaningless at 300 (design §Gap C). Without it a dismissal
//     COUNT is not a dismissal RATE.
// Latency needs no column — `voted_at − fired_at` on a dismissed row already
// separates "swatted it instantly, it's noise" (<1s) from "read it, acted, then
// cleared it" (several seconds). Those are opposite verdicts.
//
// Scope, per docs/DESIGN-trigger-overlay-v2.md: per-user and session-scoped BY
// CONSTRUCTION. A dismissal clears the row in this agent only — it never
// relays, never touches guild_triggers, and dies with the process. One raider
// clearing a Death Touch bar must never clear the raid's.
//
// Votes are BATCHED (30s / 25 rows) into one upload: `expired` fires once per
// countdown per raider, so a per-row POST would put hundreds of tiny requests
// on the ingest surface for a signal that is only ever read in aggregate.
const CALLOUT_FEEDBACK_RECENT_MAX = 12;
const CALLOUT_VOTE_FLUSH_MS  = 30_000;
const CALLOUT_VOTE_MAX_BATCH = 25;
const _calloutFeedback = { dismissed: 0, expired: 0, uploaded: 0, recent: [] };
const _calloutVoteBuffer = [];
let _calloutVoteFlushTimer = null;
function _flushCalloutVotes() {
  if (_calloutVoteFlushTimer) { clearTimeout(_calloutVoteFlushTimer); _calloutVoteFlushTimer = null; }
  if (_calloutVoteBuffer.length === 0) return 0;
  const votes = _calloutVoteBuffer.splice(0, _calloutVoteBuffer.length);
  enqueueUpload('trigger_feedback', { agent_version: AGENT_VERSION, votes });
  _calloutFeedback.uploaded += votes.length;
  return votes.length;
}
function _queueCalloutVote(vote) {
  _calloutVoteBuffer.push(vote);
  if (_calloutVoteBuffer.length >= CALLOUT_VOTE_MAX_BATCH) return _flushCalloutVotes();
  if (!_calloutVoteFlushTimer) {
    _calloutVoteFlushTimer = setTimeout(_flushCalloutVotes, CALLOUT_VOTE_FLUSH_MS);
    if (_calloutVoteFlushTimer.unref) _calloutVoteFlushTimer.unref();
  }
  return 0;
}
// The active character, same 60s-freshness rule the timing-vote endpoint uses.
function _calloutVoterCharacter() {
  let active = null, activeTs = 0;
  const now = Date.now();
  for (const ch of Object.keys(_zealState || {})) {
    const st = _zealState[ch]; const ts = (st && st.updatedAt) || 0;
    if (ts > activeTs && (now - ts) < 60_000) { activeTs = ts; active = ch; }
  }
  return active;
}
// e: { direction, timer? , trigger_id?, trigger_name?, firedAtMs?, source?, test? }
function _recordCalloutFeedback(e) {
  if (!e) return null;
  const dir = e.direction === 'expired' ? 'expired' : 'dismissed';
  const row = e.timer || null;
  // A loot-auction chip is a BID WINDOW, not a callout. Its ✕ means "I've bid"
  // or "not for me" and says nothing about whether a trigger was useful, so it
  // must never enter the learning set (#107/#129).
  if (row && row.kind === 'loot') return null;
  const name = String((row && (row.trigger_name || row.effect || row.name))
                      || e.trigger_name || '(unknown trigger)').slice(0, 200);
  const triggerId = (row && row.trigger_id) || e.trigger_id || null;
  const firedMs = Number(e.firedAtMs) || (row && row.started_at_ms) || Date.now();
  const atMs = Date.now();
  const isTest = !!(e.test || (row && row.test));
  const entry = {
    at:         atMs,
    direction:  dir,
    trigger:    name,
    latency_ms: Math.max(0, atMs - firedMs),
    source:     String(e.source || 'callout').slice(0, 40),
    test:       isTest,
  };
  _calloutFeedback[dir]++;
  _calloutFeedback.recent.push(entry);
  if (_calloutFeedback.recent.length > CALLOUT_FEEDBACK_RECENT_MAX) _calloutFeedback.recent.shift();
  console.log('[callout] ' + dir + ' — ' + name + ' after ' + Math.round(entry.latency_ms / 1000) + 's'
              + (isTest ? ' (test/rehearsal — not uploaded)' : ''));
  // A rehearsal or a ⏪ replay drives the whole path on purpose — that is how
  // this gets tested without a raid — but a test drive is not a raider's
  // verdict, so it stops at the local counters.
  if (isTest) return entry;
  _queueCalloutVote({
    trigger_id:      triggerId ? String(triggerId).slice(0, 120) : null,
    trigger_name:    name,
    direction:       dir,
    fired_at:        new Date(firedMs).toISOString(),
    voted_at:        new Date(atMs).toISOString(),
    voter_character: _calloutVoterCharacter(),
    note:            entry.source,
  });
  return entry;
}
// Local, in-memory view for /api/state — how the overlay's ✕ is verified
// without a raid (and without waiting on an upload round-trip).
function _calloutFeedbackSnapshot() {
  return {
    dismissed: _calloutFeedback.dismissed,
    expired:   _calloutFeedback.expired,
    uploaded:  _calloutFeedback.uploaded,
    pending:   _calloutVoteBuffer.length,
    recent:    _calloutFeedback.recent.slice().reverse(),
  };
}

function _activeTimersSnapshot() {
  const now = Date.now();
  const out = [];
  for (const [id, t] of _activeTimers) {
    // Aged out untouched — the control group for the dismissal rate (#207).
    // Only a NATURAL expiry lands here: a mob-death cancel and a user dismissal
    // both delete the row themselves, so neither is double-counted.
    if (t.ends_at_ms <= now) {
      _activeTimers.delete(id);
      try { _recordCalloutFeedback({ direction: 'expired', timer: t, source: 'timer_expired' }); }
      catch { /* never let bookkeeping break the snapshot */ }
      continue;
    }
    // display_threshold_sec: hide the row until it is nearly up ("only show me
    // the last 30s"). Filtered HERE rather than in the overlay so an older
    // bundled triggers.html gets the behaviour without a Mimic update.
    if (t.show_at_ms > 0 && (t.ends_at_ms - now) > t.show_at_ms) continue;
    out.push({
      id:           t.id,
      name:         t.name,
      target:       t.target || null,   // GINA-style row prefix (boss/mob)
      effect:       t.effect || t.name, // GINA-style row suffix (spell/effect)
      remaining_ms: t.ends_at_ms - now,
      duration_sec: t.duration_sec,
      color:        t.color,
      end_text:     t.end_text,
      warning_ms:   t.warn_ms || 0,
      warn_text:    t.warn_text || null,
      warnings:     Array.isArray(t.warnings) ? t.warnings : [],
      bar_color:    t.bar_color || null,
      pinned:       !!t.pinned,
      scope:        t.scope,
      // #107 loot chips carry kind:'loot' + dismissible so the trigger overlay
      // draws a per-chip ✕ (deathtouch timers stay non-dismissible as before).
      kind:         t.kind || null,
      dismissible:  !!t.dismissible,
      test:         t.test,
    });
  }
  // Soonest-to-expire first — that's the most useful default for a stack of bars.
  // Pinned rows float as a GROUP above unpinned, then soonest-first within
  // each — so a 3-minute boss-cadence bar stays on top instead of sinking
  // under six 20-second rows on a busy pull.
  out.sort((a, b) => (b.pinned === true) - (a.pinned === true) || a.remaining_ms - b.remaining_ms);
  return out;
}

// ── #107/#149 Loot-post announce + auction countdown chip ───────────────────
// The auction chip + the "Loot posted" TTS open from the bot's loot-posted
// BROADCAST (an officer's /loot post → recent-fires payload → _consumeLootPosted
// above), NOT from chat-sniffing. The broadcast carries the officer's chosen
// window (window_sec), so the chip's countdown matches the real bid window (#129).
// The TTS rides the SAME overlay fire pipeline as triggers (_pushOverlay →
// recentTriggerFires → triggers.html speaks it only when the master
// `enableTriggerTts` flag is on), and the chip reuses the trigger _activeTimers
// machinery so it looks/behaves exactly like a Death Touch countdown.
//
// noteLootAuction (chat) is now a NARROW helper: it never opens a chip and never
// speaks — it only re-anchors an already-open (broadcast-opened) auction's
// window when a bid call STATES a duration (the "drop list … then 'bids, 2
// minutes'" two-line officer workflow). The passive Loot Capture panel
// (noteLootFromChat) is a separate, untouched consumer of the same chat lines.
const _lootAuctions = new Map();   // sig → { items, openedAtMs, channel }
let _lastLootSig     = null;
// Words that mark a bid call. Kept broad but anchored on \b so it doesn't fire
// on substrings ("forbidden", "auctioneer" etc. still match "bid"/"auction" as
// whole words only where intended).
const LOOT_BID_CALL_RX = /\b(bids?|bidding|dkp|auctions?|going once|going twice|min bid|starting bid)\b/i;

function _lootAuctionDefaultSec() {
  const v = _optinState.lootAuctionDefaultSec;
  return Number.isFinite(v) ? Math.max(15, Math.min(1800, Math.round(v))) : 120;
}

// Snapshot the live loot-auction detection for the #108 Loot bidding panel
// (GET /api/loot/auctions). ONE source of truth — reads _lootAuctions +
// their countdown chips in _activeTimers; no re-parse. Elapsed windows drop.
function _lootAuctionsSnapshot(nowMs) {
  const now = Number.isFinite(nowMs) ? nowMs : Date.now();
  const out = [];
  for (const [sig, a] of _lootAuctions) {
    const timer = _activeTimers.get('loot|' + sig);
    const endsMs = timer ? timer.ends_at_ms : null;
    if (endsMs && endsMs < now) continue;   // window elapsed — drop
    out.push({
      sig,
      items:     (a.items || []).map(it => ({ name: it.name, quantity: it.quantity || 1 })),
      opened_at: a.openedAtMs ? new Date(a.openedAtMs).toISOString() : null,
      ends_at:   endsMs ? new Date(endsMs).toISOString() : null,
      channel:   a.channel || null,
    });
  }
  return out;
}

// Tolerant duration parse: "2 min", "2 minutes", "2m", "90 sec", "90s",
// "90 seconds". Minutes win when both a bare number+unit appear. Clamped so a
// stray "600 minutes" can't pin a chip on-screen forever.
function _parseAuctionDuration(text) {
  if (!text) return null;
  const s = String(text);
  let m = s.match(/(\d{1,3})\s*(?:min(?:ute)?s?|m)\b/i);
  if (m) { const v = parseInt(m[1], 10); if (v >= 1 && v <= 30) return v * 60; }
  m = s.match(/(\d{1,4})\s*(?:sec(?:ond)?s?|s)\b/i);
  if (m) { const v = parseInt(m[1], 10); if (v >= 10 && v <= 1800) return v; }
  return null;
}

// Spoken form of a duration for the TTS callout.
function _spokenDuration(sec) {
  sec = Math.round(sec);
  if (sec % 60 === 0) { const mm = sec / 60; return mm + (mm === 1 ? ' minute' : ' minutes'); }
  if (sec < 60) return sec + ' seconds';
  const mm = Math.floor(sec / 60), ss = sec % 60;
  return mm + (mm === 1 ? ' minute ' : ' minutes ') + ss + ' seconds';
}

// Chip label — a single item names it; multiple items count.
function _lootChipLabel(items) {
  if (items.length === 1) {
    const it = items[0];
    return '💰 Bids — ' + it.name + (it.quantity > 1 ? ' (x' + it.quantity + ')' : '');
  }
  return '💰 Loot bids (' + items.length + ')';
}

function _announceLootPost(items, durSec) {
  const distinct = items.length;
  const itemWord = distinct === 1 ? 'item' : 'items';
  const durPhrase = _spokenDuration(durSec);
  const spoken = 'Loot posted — ' + distinct + ' ' + itemWord + ', bids open ' + durPhrase;
  _pushOverlay({
    text:        '💰 Loot posted — ' + distinct + ' ' + itemWord + ' · bids ' + durPhrase,
    tts:         spoken,
    color:       'gold',
    duration_ms: 6000,
    shownAt:     Date.now(),
    firedAt:     Date.now(),
    trigger:     'Loot auction',
    scope:       'loot',
    test:        false,
  });
}

// Open (or restart) an auction chip for this item set. Same signature =
// restart in place (repeat post RESETS, never stacks a duplicate); a distinct
// item set = a new independent chip (concurrent auctions are real). The TTS
// callout fires only on the FIRST open of a set — second-watched-log copies
// and repeat posts reset silently.
function _openOrResetLootAuction(sig, items, durSec, nowMs, channel, silent) {
  const id = 'loot|' + sig;
  const existed = _activeTimers.has(id);
  const label = _lootChipLabel(items);
  const warnMs = durSec > 25 ? 15000 : 0;
  _activeTimers.set(id, {
    id,
    name:          label,
    target:        null,
    effect:        label,
    started_at_ms: nowMs,
    ends_at_ms:    nowMs + durSec * 1000,
    duration_sec:  durSec,
    color:         'gold',
    end_text:      null,
    warn_ms:       warnMs,
    warn_text:     warnMs ? ('15 seconds left — ' + (items.length === 1 ? items[0].name : items.length + ' item bids')) : null,
    trigger_name:  null,
    captures:      null,
    scope:         'loot',
    kind:          'loot',
    dismissible:   true,
    test:          false,
  });
  _lootAuctions.set(sig, { items, openedAtMs: nowMs, channel });
  _lastLootSig = sig;
  if (!existed && !silent) _announceLootPost(items, durSec);
  scheduleRender();
}

// Chat entry point — called for every live /gu + /rs line (NOT the --since
// backfill, which replays history and must not touch live auctions).
//
// #149: chip-opening + the spoken callout were RETIRED from this path — they now
// come from the bot's loot-posted broadcast (_consumeLootPosted). What remains
// is duration RE-ANCHORING: a bid call that states a duration ("bids, 2 minutes")
// resets the window of the most-recent already-open (broadcast-opened) auction.
// It NEVER opens a new chip and NEVER speaks (the re-anchor is silent), so it is
// not gated by lootAuctionTts — the chip/timer is decoupled from the voice
// toggle. A drop-list line with no open auction is a NO-OP here (still captured
// by the separate, untouched noteLootFromChat → Loot Capture panel).
function noteLootAuction(chatMsg) {
  try {
    if (!chatMsg || (chatMsg.channel !== 'guild' && chatMsg.channel !== 'raid')) return;
    const text  = String(chatMsg.text || '');
    if (!LOOT_BID_CALL_RX.test(text)) return;        // only bid calls re-anchor
    const statedDur = _parseAuctionDuration(text);
    if (statedDur == null) return;                   // no stated window → nothing to re-anchor
    if (!_lastLootSig || !_lootAuctions.has(_lastLootSig)) return;   // no open auction to re-time
    const nowMs = Date.parse(chatMsg.ts) || Date.now();
    const a = _lootAuctions.get(_lastLootSig);
    if ((nowMs - a.openedAtMs) < 120_000) {
      _openOrResetLootAuction(_lastLootSig, a.items, statedDur, nowMs, a.channel, true);
    }
  } catch (e) { void e; }
}

// Action-text expansion — every reference dialect that shows up in imported
// packs: ${name}/${2} (GINA — the $ is consumed), {name}/{2}/{0} (native +
// EQLogParser), $1/$2 (.NET replacement form). Anything unresolved is left
// EXACTLY as written so literal braces and dollar signs in a callout survive.
// The captures arg is the _buildCaptureBag output on live fires, so "{1}",
// "${2}", "{L}" and folded duplicate names all resolve; older callers passing
// a plain object keep working (lookup is just key access).
function _expandTemplate(template, captures) {
  if (!template) return '';
  const bag = captures || {};
  const lookup = (whole, k) => {
    if (bag[k] != null) return String(bag[k]);
    const lower = String(k).toLowerCase();
    if (bag[lower] != null) return String(bag[lower]);
    return whole;
  };
  let out = String(template);
  out = out.replace(/\$\{([A-Za-z0-9_]+)\}/g, lookup);
  out = out.replace(/\{([A-Za-z0-9_]+)\}/g, lookup);
  out = out.replace(/\$(\d)/g, lookup);
  return out;
}

// ── Trigger checkpoint journal (#76) ────────────────────────────────────────
// "Why didn't my trigger fire?" answered from the dashboard. A small in-memory
// ring buffer (NO disk, NO upload) records, per candidate evaluation, how far
// it got through the pipeline and — when it stopped short — why. A candidate is
// any evaluation whose pattern MATCHED a line (live) or a REHEARSE run (which
// records checkpoint 1 even when the pattern is never exercised). Recording
// every trigger against every line would flood the buffer, so live entries
// begin at "pattern matched"; the rehearse path is what surfaces a pattern
// that never matches at all.
const TRIGGER_JOURNAL_MAX = 250;
const _triggerJournal = [];   // append newest at end; capped at TRIGGER_JOURNAL_MAX
// Checkpoint ladder — higher = further through the pipeline.
// PLAYBACK (5b, #120) sits between DISPATCHED and RELAYED: "dispatched" only
// means the overlay pushed a fire + called speechSynthesis.speak() — it does
// NOT prove any audio came out. The trigger overlay reports the real playback
// outcome (onstart / onerror / silent-timeout) to /api/triggers/playback so a
// machine where Chromium's user-activation gate silently swallows speech (the
// "no Mimic entry in the Windows volume mixer" field bug) lights up here
// instead of looking like a clean checkpoint-5 dispatch.
const TJ = { SEEN: 1, MATCHED: 2, GATES: 3, ACTIONS: 4, DISPATCHED: 5, PLAYBACK: 5.5, RELAYED: 6 };
const TJ_LABEL = { 1: 'line seen', 2: 'pattern matched', 3: 'gates passed',
                   4: 'actions built', 5: 'dispatched', 5.5: 'playback', 6: 'relayed' };
function _journalTrigger(e) {
  const cp = e.checkpoint || 0;
  _triggerJournal.push({
    at:         e.at || Date.now(),
    trigger:    String(e.trigger || '?').slice(0, 80),
    scope:      e.scope || '?',
    checkpoint: cp,
    label:      e.label || TJ_LABEL[cp] || '?',
    reason:     e.reason ? String(e.reason).slice(0, 160) : null,
    rehearsal:  !!e.rehearsal,
    // #101 log-replay marker — a rehearsal fire produced by walking an old log
    // through the real pipeline (distinct from an interactive Rehearse click).
    replay:     !!e.replay,
    // Stopped short = didn't reach dispatch. Drives the ✓/✗ column colour.
    stopped:    e.stopped != null ? !!e.stopped : (cp < TJ.DISPATCHED),
  });
  if (_triggerJournal.length > TRIGGER_JOURNAL_MAX) {
    _triggerJournal.splice(0, _triggerJournal.length - TRIGGER_JOURNAL_MAX);
  }
}

// Best-effort synthesizer: build a literal log line that the trigger's compiled
// _regex accepts, so REHEARSE can drive the pattern through the REAL evaluator
// instead of firing the action directly (false confidence). Strips regex
// scaffolding to a plausible EQ line, substitutes any provided captures for
// named groups, then VERIFIES with the real regex — returns null if it can't
// produce a match (caller then rehearses the action tail only and journals
// "pattern not exercised"). Handles the common EQ trigger shapes; exotic
// patterns simply fall through to the null path.
function _synthesizeMatchingLine(t, captures) {
  if (!t || !t._regex) return null;
  let src = String(t.pattern || '');
  if (!src.trim()) return null;
  // Literal-match triggers: the pattern IS the substring to match.
  if (t.use_regex === false) {
    return src;
  }
  const caps = captures || {};
  // Named group → the provided capture, else a neutral placeholder token.
  src = src.replace(/\(\?<([A-Za-z_][\w]*)>[^)]*\)/g, (_, name) =>
    (caps[name] != null ? String(caps[name]) : 'Testmob'));
  // Remaining groups (non-capturing / plain) → first alternative, parens gone.
  src = src.replace(/\(\?:([^)|]*)(?:\|[^)]*)?\)/g, '$1');
  src = src.replace(/\(([^)|]*)(?:\|[^)]*)?\)/g, '$1');
  // Character classes / metaclasses → representative literals.
  src = src.replace(/\\d(?:\{[\d,]+\})?|\[0-9\][+*?]?/g, '42');
  src = src.replace(/\[[^\]]*\][+*?]?/g, 'x');
  src = src.replace(/\\w[+*?]?/g, 'word');
  src = src.replace(/\\s[+*?]?/g, ' ');
  src = src.replace(/\.[+*?]/g, 'something');
  // Drop quantifiers on literals and the end anchor; a LEADING ^ is honoured
  // by prepending a synthetic timestamp below, so REHEARSE chews on the same
  // raw-line shape the live tail produces. The old blanket anchor delete made
  // a ^-anchored pattern rehearse green while being dead on live (the
  // false-green half of the pq-companion 01 findings).
  src = src.replace(/[?*+]/g, '');
  src = src.replace(/\$$/, '');
  if (src.startsWith('^')) src = src.slice(1);
  src = src.replace(/[\^$]/g, '');
  src = '[Thu Aug 07 12:00:00 2026] ' + src;
  src = src.replace(/\\([.\-+*?()\[\]{}|^$/])/g, '$1');
  src = src.replace(/\s{2,}/g, ' ').trim();
  try { return t._regex.test(src) ? src : null; }
  catch { return null; }
}

// Real REHEARSE (#76): drive a trigger through the actual evaluation pipeline —
// pattern exec, cooldown check, charm-pet suppression, then the action tail —
// flagged as a rehearsal so it (a) never relays/uploads, (b) never touches
// _fireLog/timeline capture, and (c) is labelled as a rehearsal in the journal
// + overlay. Cooldown + suppression verdicts are EVALUATED and journalled but
// NOT enforced (a rehearsal always reaches dispatch so the user hears the real
// TTS) and NEVER consume the real cooldown (_triggerLastFire untouched).
function _rehearseTrigger(t, opts) {
  opts = opts || {};
  const name = t.name || 'trigger';
  const scope = 'rehearsal';
  const notes = [];
  let captures = (opts.captures && typeof opts.captures === 'object') ? opts.captures : {};
  // Checkpoint 1 — the engine "sees" a line (synthesized unless the caller
  // supplied one via the pattern-test panel).
  let line = opts.line || null;
  let patternExercised = false;
  if (!t._regex) {
    // No log pattern to satisfy — either a pure-Zeal gauge-condition trigger
    // or an ad-hoc action-only preview.
    notes.push(t.zeal_condition ? 'pattern not exercised (gauge condition)'
                                : 'pattern not exercised (no log pattern)');
  } else {
    if (!line) line = _synthesizeMatchingLine(t, captures);
    if (line) {
      let m = null;
      try { m = t._regex.exec(line); } catch { m = null; }
      if (m) {
        patternExercised = true;
        captures = Object.assign({}, m.groups || {}, captures);
        notes.push('pattern matched synthesized line');
      } else {
        notes.push('pattern not exercised (could not synthesize a matching line)');
      }
    } else {
      notes.push('pattern not exercised (could not synthesize a matching line)');
    }
  }
  // Checkpoint 3 — evaluate the gates for REPORTING only.
  if (patternExercised && _captureMatchesCharmPet(captures)) {
    notes.push('would be suppressed live (capture is your charm pet)');
  }
  if (t.cooldown_seconds && t.cooldown_seconds > 0) {
    const last = _triggerLastFire.get(t.id || t.name) || 0;
    const remain = (t.cooldown_seconds * 1000) - (Date.now() - last);
    if (remain > 0) notes.push('would be on cooldown live (' + Math.ceil(remain / 1000) + 's left)');
  }
  // Dispatch the action tail through the SAME handler as a live fire, marked
  // as a rehearsal: test=true skips _fireLog + relay + Discord, _rehearsal
  // labels the overlay + suppresses the handler's own journal row (we write a
  // single comprehensive one below).
  const rehearseTrig = Object.assign({}, t, { _scope: scope, _rehearsal: true, _noJournal: true });
  _fireTriggerActions(rehearseTrig, captures, Date.now(), true);
  _journalTrigger({
    trigger:   name,
    scope,
    rehearsal: true,
    checkpoint: TJ.DISPATCHED,
    stopped:   false,
    reason:    'rehearsal — ' + notes.join('; ') + '; cooldown/suppression not consumed',
  });
  return { patternExercised, line: line || null, captures };
}

// Hot-path: called for every kept log line in the tail loop.
function evaluateTriggersAgainstLine(line, tsMs) {
  const all = [..._personalTriggers, ...(stats.guildTriggers || [])];
  if (all.length === 0) return;
  for (const t of all) {
    // End-early check runs FIRST so a single log line containing the end
    // phrase cancels the timer before the same line could (also) re-trigger
    // the start pattern. Per-target: if the end pattern matches and there
    // are multiple timers from this trigger (different captures), only the
    // one whose captures match the end-line's captures cancels. Otherwise
    // all timers under this trigger cancel — matches the simple case where
    // a trigger has only one active timer.
    if (t._endRegex) {
      try {
        const em = t._endRegex.exec(line);
        if (em) {
          const endCaps = em.groups || {};
          const triggerName = t.name;
          for (const [tid, row] of _activeTimers) {
            if (row.trigger_name !== triggerName) continue;
            const rowCaps = row.captures || {};
            const captureKeys = Object.keys(rowCaps);
            const hasCaps = captureKeys.length > 0 && Object.keys(endCaps).length > 0;
            if (hasCaps) {
              // Require every shared capture key to match (case-insensitive)
              // before cancelling. If the end pattern names different
              // captures than the start, we treat it as "trigger-wide"
              // cancellation below.
              const sharedKeys = captureKeys.filter(k => endCaps[k] != null);
              if (sharedKeys.length > 0) {
                const allMatch = sharedKeys.every(k =>
                  String(rowCaps[k]).toLowerCase() === String(endCaps[k]).toLowerCase());
                if (allMatch) _activeTimers.delete(tid);
                continue;
              }
            }
            _activeTimers.delete(tid);
          }
        }
      } catch { /* bad end-early regex — already logged at compile time */ }
    }
    if (!t._regex) continue;
    let m;
    try { m = t._regex.exec(line); } catch { continue; }
    if (!m) continue;
    // GINA numeric guards ({N>=50000}): the capture matched, but the trigger
    // only fires when the number clears the threshold. Cheap — most triggers
    // carry no conditions at all.
    if (t._conditions && t._conditions.length && !_captureConditionsPass(t._conditions, m.groups)) {
      _journalTrigger({ trigger: t.name, scope: t._scope || 'personal', checkpoint: TJ.GATES,
                        stopped: true, reason: 'numeric guard not met' });
      continue;
    }
    // exclude_patterns — the line matched, but something on the exclude list
    // matched it too, so this is one of the cases the author carved out.
    if (t._excludes && t._excludes.length && t._excludes.some(rx => rx.test(line))) {
      _journalTrigger({ trigger: t.name, scope: t._scope || 'personal', checkpoint: TJ.GATES,
                        stopped: true, reason: 'suppressed — matched an exclude pattern' });
      continue;
    }
    // Charm-pet filter — if the captured {s} name is one of our currently
    // active charm pets, the message is about OUR pet (slow on a charmed
    // mob, our pet enrages at low HP, etc.) and the call would be wrong.
    // Don't apply to Zeal-condition triggers (no log-match captures there).
    const captures = _buildCaptureBag(m, line, {}, t._aliases);
    if (_captureMatchesCharmPet(captures)) {
      _journalTrigger({ trigger: t.name, scope: t._scope || 'personal', checkpoint: TJ.MATCHED,
                        stopped: true, reason: 'suppressed — capture is your charm pet' });
      continue;
    }
    // Cooldown gate
    if (t.cooldown_seconds && t.cooldown_seconds > 0) {
      const last = _triggerLastFire.get(t.id || t.name) || 0;
      if (tsMs - last < t.cooldown_seconds * 1000) {
        _journalTrigger({ trigger: t.name, scope: t._scope || 'personal', checkpoint: TJ.GATES,
                          stopped: true, reason: 'cooldown — ' + Math.ceil((t.cooldown_seconds * 1000 - (tsMs - last)) / 1000) + 's remaining' });
        continue;
      }
    }
    _triggerLastFire.set(t.id || t.name, tsMs);
    _fireTriggerActions(t, captures, tsMs, false);
  }
}

// Fire a trigger's actions WITHOUT requiring a live-line match. Used by both:
//   • evaluateTriggersAgainstLine (the live evaluator)
//   • POST /api/triggers/fire (the dashboard's "Test" / "Preview" buttons)
//
// All writes are in-memory only — _pushOverlay populates the ring buffer the
// dashboard + overlay window read, console.log echoes to the CLI, and
// scheduleRender pokes the dashboard. NO database, NO upload queue, NO Discord
// — test fires are local-only by construction. The `test` flag on the
// emitted overlay lets the UI label test fires distinctly.
// Lowercased set of names from the current Zeal raid roster. Re-populated by
// _maybeUploadRaidRoster on every raid-window change; trigger actions can opt
// in to "only fire when capture X is in this set" via require_raid_member
// (covers: pet names, hammer pets, mob substrings that backtrack-match a
// player-shaped pattern). Empty when no raid window has been seen — in that
// case the filter falls open (any captured name is allowed) so non-raid
// triggers still work.
const _raidRosterMembers = new Set();
// nameLower → class ("Cleric", "Druid", …) from the same Zeal type-5 sample.
// The Healer Mana roster resolves class through this when /who data is absent
// — /who-only resolution left class null for most of the raid and the healer
// filter dropped them all ("We no longer see Cleric/CH chain Mana", 2026-07-09).
const _raidClassByName = new Map();
function _raidRosterHas(name) {
  if (!name || _raidRosterMembers.size === 0) return false;
  return _raidRosterMembers.has(String(name).toLowerCase());
}
// #150 — a captured name that is one of OUR pets (charm or summoned). The
// require_raid_member gate below must PASS for a Death-Touch-on-a-pet: a pet is
// never in the Zeal raid roster, so the gate used to suppress the DT countdown
// when the boss DT'd a charm/summoned pet. Covers all three ownership signals
// the DPS meter uses: _charmTickTracker + Zeal slot-16 (via _petOwnerByName)
// and the cross-builder declared pet-leaders registry (knownPetOwners, the
// global equivalent of an EncounterBuilder's petLeaders / _activeCharms).
// Genuinely-unknown non-pet non-members are unaffected — they still suppress.
function _isOurPetName(nameLower) {
  if (!nameLower) return false;
  return !!_petOwnerByName(nameLower) || knownPetOwners.has(nameLower);
}

// ── #136 Raid callout allow-list ─────────────────────────────────────────────
// The guild-wide voice path fans out EVERY raider's guild-trigger fire to
// everyone (a local guild fire → _relayLocalFire → the bot's recent-fires →
// _consumeRelayFires → _runRelayedFire → _fireTriggerActions on every other
// Mimic). Field feedback: that firehose speaks per-raider noise — individual
// heals, personal INCs, generic trigger chatter relayed from other clients —
// on everyone's machine. This allow-list MUTES guild-pushed + cross-client
// RELAYED fires that don't match one of the high-value categories the guild
// lead asked to keep audible. Two hard rules:
//   • LOCAL personal triggers (the user's own, _scope 'personal') are NEVER
//     gated — the user opted in by creating them.
//   • The curated built-in callouts (rampage, buster, AoE-dance, slow land/drop,
//     CH GO, loot) reach the overlay through their OWN direct _pushOverlay path
//     and never pass through this gate at all, so they always speak. The phrase
//     matcher below ALSO keeps any guild trigger — or a relayed built-in like
//     'New Rampage' — audible when its name/tags/text carry those words.
// A muted fire still RENDERS (flash) on the trigger overlay; only speech is
// suppressed (overlay.mute → triggers.html skips speak(), keeps flash()) —
// visibility without noise.
const _CALLOUT_ALLOW_CATEGORIES = [
  { cat: 'slow',       rx: /\bslow(?:ed|s|ing)?\b|reslow|un-?slow/i },
  { cat: 'death',      rx: /\bdeath\b|\bdead\b|\bdied\b|\bdies\b|\bslain\b|has been slain|\bR\.?I\.?P\.?\b|\brez\b|\bresurrect/i },
  { cat: 'tank swap',  rx: /tank\s*swap|swap\s*tank|tankswap|\bpeel\b|off[-\s]?tank/i },
  { cat: 'disc',       rx: /\bdiscs?\b|\bdiscipline/i },
  { cat: 'deathtouch', rx: /death\s*touch|deathtouch|\bDT\b/i },
  { cat: 'charm',      rx: /\bcharm(?:ed|s|ing)?\b|charm\s*(?:break|broke|broken)/i },
  // Boss-mechanic countdowns already curated in the built-ins — keep audible
  // even when a guild trigger drives them (e.g. a voice-mark sequence).
  { cat: 'mechanic',   rx: /\bbuster\b|tank\s*buster|\baoe\b|\bdance\b|\brampage\b|\bch\s*go\b|\bloot\b/i },
];
// Is this trigger (or relayed fire) allowed to SPEAK under the allow-list? Scans
// the trigger name, its tags (guild_triggers rows carry `tags`; array or CSV
// string both handled), and every action's display/tts/message text (+ voice
// marks). Any category hit → allowed. An empty haystack (no name, no tags, no
// text) → NOT allowed: an unnamed, untagged, text-less fire is exactly the
// noise the field asked us to mute.
function _calloutAllowedToSpeak(t) {
  if (!t) return false;
  const parts = [];
  if (t.name) parts.push(String(t.name));
  const tags = t.tags;
  if (Array.isArray(tags)) parts.push(tags.join(' '));
  else if (typeof tags === 'string') parts.push(tags);
  for (const a of (t.actions || [])) {
    if (!a) continue;
    if (a.text)    parts.push(String(a.text));
    if (a.tts)     parts.push(String(a.tts));
    if (a.message) parts.push(String(a.message));
    if (Array.isArray(a.marks)) {
      for (const m of a.marks) { if (m && (m.text || m.message)) parts.push(String(m.text || m.message)); }
    }
  }
  const hay = parts.join('  ');
  if (!hay.trim()) return false;
  for (const c of _CALLOUT_ALLOW_CATEGORIES) { if (c.rx.test(hay)) return true; }
  return false;
}
// A fire on this scope must pass the allow-list to speak — only the raid-wide
// voice paths: locally-fired GUILD triggers and cross-client RELAYED fires.
// Personal / built-in / test / replay fires bypass entirely.
function _calloutScopeGated(scope) {
  return scope === 'guild' || scope === 'guild_relay';
}

function _fireTriggerActions(t, captures, tsMs, test, isRelay) {
  // GINA's {COUNTER} — session-scoped per-trigger fire tally, available to
  // every action template. Test/replay fires read the count without bumping
  // it, so a rehearsal can't skew a live "third add incoming" counter.
  const _fcKey = t.id || t.name;
  const _fc = (_triggerFireCounts.get(_fcKey) || 0) + (test ? 0 : 1);
  if (!test) _triggerFireCounts.set(_fcKey, _fc);
  if (captures && captures.counter == null) captures.counter = _fc;
  // #136 raid callout allow-list — decide ONCE per fire whether speech is muted.
  // Applies only to the raid-wide voice scopes (guild + relayed), only when the
  // allow-list is enabled, and only when the trigger matches no critical
  // category. Personal + test/replay fires are never muted. The muted overlay
  // still flashes; triggers.html reads overlay.mute and skips speak().
  const _calloutMuted = !test
    && _optinState.calloutAllowlist !== false
    && _calloutScopeGated(t._scope)
    && !_calloutAllowedToSpeak(t);
  // Trigger-level roster gate. The require_raid_member field lives on
  // individual actions (so a single trigger can have one filtered + one
  // unfiltered action), but the trigger-level countdown timer is a single
  // shared concept — it'd be wrong to render a Death Touch countdown bar
  // for a pet who took 20k non-melee damage and then suppress just the
  // overlay text. So: if ANY action sets require_raid_member AND that
  // capture isn't in the roster, treat the whole trigger as suppressed
  // (no actions, no timer). Falls open when roster is empty (haven't
  // seen Type 5 yet) so out-of-raid testing still fires.
  if (_raidRosterMembers.size > 0) {
    for (const a of (t.actions || [])) {
      if (!a || !a.require_raid_member) continue;
      const val = captures && captures[String(a.require_raid_member)];
      // Pass when the captured name is a raid member OR one of our pets (#150);
      // only a genuinely-unknown non-pet non-member suppresses.
      if (!val || (!_raidRosterHas(val) && !_isOurPetName(String(val).toLowerCase()))) {
        // TIMER-BEARING triggers still ARM on a suppressed fire (Hitya
        // 2026-08-19, second cursed-cycle DT landed on a pet and the raid
        // had no countdown): a countdown is CYCLE state, not a victim
        // callout — a Death Touch spent on ANY pet still means the next one
        // is timer_duration away, and most agents can't prove someone
        // else's charm pet is "ours". Only the gated actions (text / tts /
        // discord) stay suppressed. The Aug-09 six-chips-for-one-name spam
        // this gate was tightened against was an id-explosion in
        // captureSuffix, fixed separately — not a reason to drop the arm.
        const hasTimer = (t.timer_duration_sec > 0 || t.timer_duration_capture);
        if (hasTimer) _startTimer(t, tsMs, test, captures);
        if (!test) console.log('[trigger] ' + (t.name || 'trigger') + ' ' + (hasTimer ? 'timer armed, actions suppressed' : 'suppressed') + ' — ' + a.require_raid_member + '=' + val + ' not a raid member');
        if (!t._noJournal) {
          _journalTrigger({ trigger: t.name, scope: t._scope || (test ? 'test' : 'personal'), checkpoint: TJ.GATES,
                            stopped: true, rehearsal: !!t._rehearsal,
                            reason: (hasTimer ? 'timer armed; actions suppressed — ' : 'suppressed — ') + a.require_raid_member + '=' + (val || '?') + ' not a raid member' });
        }
        return;
      }
    }
  }
  // Checkpoint bookkeeping for the journal (#76): how far this fire actually got.
  let _dispatched = false;
  let _actionsBuilt = 0;
  // Callout-replay (#98): record the fire so the per-fight timeline can show
  // which callouts went off. Skip test/rehearsal fires. Windowed into the
  // encounter at flush time; hard-capped so it can't grow unbounded.
  if (!test) {
    _fireLog.push({ at: tsMs || Date.now(), name: t.name || t.key || 'trigger' });
    if (_fireLog.length > 600) _fireLog.splice(0, _fireLog.length - 600);
  }
  for (const a of (t.actions || [])) {
    if (!a || !a.type) continue;
    _actionsBuilt++;
    if (a.type === 'text_overlay') {
      const text = _expandTemplate(a.text || '', captures || {});
      // Spoken text: an explicit per-action `tts` wins (lets a trigger say
      // something different than it shows — e.g. EQLP TextToSpeak vs
      // TextToDisplay). When absent, the overlay window falls back to the
      // display text so every alert is audible by default.
      const ttsText = a.tts ? _expandTemplate(a.tts, captures || {}) : '';
      const overlay = {
        text,
        color:       a.color || 'red',
        duration_ms: a.duration_ms || 5000,
        shownAt:     tsMs || Date.now(),
        // firedAt is a real-time monotonic-ish stamp the trigger overlay window
        // uses to detect NEW fires (log ts can collide within a second and get
        // de-duped, swallowing rapid back-to-back alerts).
        firedAt:     Date.now(),
        trigger:     t.name,
        trigger_id:  t.id || null,   // #207 — attribution for a dismissal
        scope:       t._scope || (test ? 'test' : 'personal'),
        test:        !!test,
      };
      if (ttsText) overlay.tts = ttsText;
      // #136 — allow-list muted this guild/relay fire: it still flashes, but
      // triggers.html skips speak() when overlay.mute is set.
      if (_calloutMuted) overlay.mute = true;
      if (a.sound) overlay.sound = a.sound;
      // Sticky critical callouts (#76): a trigger-level OR action-level `sticky`
      // flag pins the alert on the trigger overlay until the user dismisses it
      // (or a generous timeout), instead of fading on the normal schedule.
      // Optional + backward-compatible: old agents ignore the field entirely.
      if (t.sticky || a.sticky) overlay.sticky = true;
      if (t._rehearsal) overlay.rehearsal = true;
      // #101 — mark overlays produced by a log replay so the UI can badge them
      // with a ⏪ tag (a replay fire is ALSO a rehearsal, so `rehearsal` is set
      // too — an overlay that only knows the older flag still shows it as a
      // rehearsal, never as a live callout).
      if (t._replay) overlay.replay = true;
      _pushOverlay(overlay);
      _dispatched = true;
      console.log(`[trigger${test ? (t._rehearsal ? ':rehearsal' : ':test') : ':' + (t._scope || '?')}] ${t.name} → ${text}`);
      scheduleRender();
    } else if (a.type === 'discord' && !test) {
      // Broadcast this fire to a text Discord channel via the bot. Test fires
      // stay local. `key` dedups across every raider's agent (default
      // name+message). Default mode is 'post'; setting `voice: true` swaps to
      // the voice surface for a one-shot speak (use 'voice' action for the
      // countdown form below).
      const msg = _expandTemplate(a.message || a.text || '', captures || {}).trim();
      if (msg) {
        const key = a.key ? _expandTemplate(a.key, captures || {}) : (t.name + ':' + msg);
        _broadcastTriggerToDiscord({
          name: t.name, message: msg, key, tsMs,
          mode: a.voice ? 'voice' : 'post',
          voiceId: a.voice_id,
        });
      }
    } else if (a.type === 'voice' && !test) {
      // Voice TTS action — one-shot or multi-tick countdown.
      //
      //   one-shot: { type: 'voice', message: 'rampage on {target}' }
      //   marks   : { type: 'voice', marks: [
      //       { at_ms: 0,     text: 'thirty seconds' },
      //       { at_ms: 20000, text: 'ten seconds, big heals' },
      //       { at_ms: 25000, text: 'five seconds, remove curse' },
      //       { at_ms: 30000, text: 'tankbuster' },
      //   ] }
      //
      // Each mark pushes a local overlay+TTS event on THIS Mimic client.
      // Mimic's renderer reads the `tts` field via the browser
      // SpeechSynthesis API, so every raider running Mimic hears the
      // call-out through their own speakers on their own machine — no
      // Discord voice gateway needed, no bot connection, no single point
      // of failure. Every raider who's running Mimic gets the audio +
      // visual independently from their own log tail.
      //
      // Marks more than 60s old at fire time are dropped (covers
      // historical replays + the case where the live log catches up
      // after a pause). Per-mark key includes its offset so 30→10→5→0
      // don't dedup to a single overlay.
      //
      // Opt-in Discord broadcast: pass `discord: true` on the action to
      // ALSO route through the bot's voice channel surface (currently
      // unreliable on Railway; kept as an option for when that's fixed).
      const baseKey  = a.key ? _expandTemplate(a.key, captures || {}) : t.name;
      const voiceId  = a.voice_id || null;
      const color    = a.color || 'red';
      const durMs    = a.duration_ms || 5000;
      const broadcastDiscord = !!a.discord;
      const speakAt  = (text, offsetMs) => {
        const msg = _expandTemplate(text || '', captures || {}).trim();
        if (!msg) return;
        // Replay rebases mark offsets onto now — a historical tsMs made every
        // fireMs more than a minute old, so the stale-drop below discarded the
        // whole 30→10→5→0 sequence and a rehearsal played nothing.
        const markBaseMs = t._replay ? Date.now() : (tsMs || Date.now());
        const fireMs = markBaseMs + Math.max(0, offsetMs || 0);
        if (Date.now() - fireMs > 60_000) return;          // stale, drop
        const delay  = Math.max(0, fireMs - Date.now());
        const key    = baseKey + ':' + Math.round(offsetMs || 0);
        setTimeout(() => {
          // Local overlay+TTS — Mimic shows the line AND speaks it. #136: a
          // muted guild/relay voice-mark still shows but stays silent.
          _pushOverlay({
            text:        msg,
            tts:         msg,
            color,
            duration_ms: durMs,
            shownAt:     Date.now(),
            firedAt:     Date.now(),
            trigger:     t.name,
            scope:       t._scope || 'personal',
            test:        false,
            mute:        _calloutMuted,
          });
          scheduleRender();
          console.log('[trigger:voice:' + (t._scope || '?') + '] ' + t.name + ' → ' + msg);
          // Optional Discord broadcast — bot routes to voice channel.
          if (broadcastDiscord) {
            _broadcastTriggerToDiscord({
              name: t.name, message: msg, key, tsMs: Date.now(),
              mode: 'voice', voiceId,
            });
          }
        }, delay);
      };
      if (Array.isArray(a.marks) && a.marks.length > 0) {
        for (const m of a.marks) speakAt(m && (m.text || m.message), m && m.at_ms);
        _dispatched = true;
      } else if (a.message || a.text) {
        speakAt(a.message || a.text, 0);
        _dispatched = true;
      }
    }
    // sound / emit_event beyond the overlay's own audio remain no-ops in v1.
  }
  // Trigger-level timer countdown (separate from per-action overlays).
  // Starts when timer_duration_sec > 0 on the trigger itself. Captures
  // are passed so per-mob keying works — "Pacify on Lord Nagafen" and
  // "Pacify on Vox" become two independent countdowns rather than the
  // second restarting the first.
  if (t.timer_duration_sec > 0 || t.timer_duration_capture) _startTimer(t, tsMs, test, captures);
  // cooldown_timer_sec: a SECOND, visible countdown for recast/reuse — distinct
  // from cooldown_seconds, which is the silent anti-spam lockout. Feign Death
  // has no duration but a 9s recast, and that was previously inexpressible.
  // target:null is deliberate — a recast bar is never per-mob, and inheriting
  // the current boss would let _cancelTimersOnMobDeath wrongly cancel it.
  if (Number(t.cooldown_timer_sec) > 0) {
    _startTimer({ ...t,
      id: String(t.id || t.name) + '::cd',
      name: (t.name || 'ability') + ' CD',
      timer_duration_sec: Number(t.cooldown_timer_sec),
      timer_duration_capture: null, timer_key_capture: null,
      timer_warnings: [{ seconds: 1, text: (t.name || 'ability') + ' ready', tts: true }],
      warning_seconds: 0, warning_text: null, pinned: false,
    }, tsMs, test, null);
  }

  // Fan-out — mark the local fire seen, then relay to the bot so other
  // Mimics that missed the source line can replay it. Skip when this
  // function is itself running a relayed fire (would loop) or for test
  // fires (debug-only, no bot side effects). Captures are part of the
  // dedup key so two simultaneously-detected DIFFERENT events
  // ("RIP Hitya" and "RIP Sweenie" within the same second) both land.
  let _relayed = false;
  if (!test) {
    // SEMANTIC captures only — the bag's `0`/`L`/`l` carry the raw line and its
    // second-resolution EQ timestamp, so two observers of the same death built
    // different keys and neither recognised the other's relay as a duplicate:
    // one local callout plus one more per observer whose clock differed by a
    // second ("REST IN PEACE" spoken twice). The behaviour the comment above
    // protects is preserved — `victim` is semantic and stays in the key, so
    // "RIP Hitya" and "RIP Sweenie" in the same second still both land.
    const fireKey = (t.name || 'trigger') + ':' + JSON.stringify(_semanticCaptures(captures));
    _markFireSeen(fireKey, tsMs || Date.now());
    if (!isRelay && t._scope !== 'personal') {
      _relayed = !!_relayLocalFire(t, t.actions || [], captures || {}, tsMs || Date.now(), fireKey);
    }
  }
  // Journal how far this fire got (#76) — one summary row per fire, unless the
  // caller (e.g. REHEARSE) writes its own comprehensive entry.
  if (!t._noJournal) {
    const cp = _relayed ? TJ.RELAYED : (_dispatched ? TJ.DISPATCHED : (_actionsBuilt > 0 ? TJ.ACTIONS : TJ.GATES));
    _journalTrigger({
      trigger:   t.name,
      scope:     t._scope || (test ? 'test' : 'personal'),
      rehearsal: !!t._rehearsal,
      checkpoint: cp,
      stopped:   cp < TJ.DISPATCHED,
      reason:    _actionsBuilt === 0 ? 'no actions on trigger' : null,
    });
  }
}

// ── #101 Log replay ─────────────────────────────────────────────────────────
// Walk a slice of an existing log file (a fight, or an arbitrary timeframe)
// back through the REAL trigger pipeline — same regex exec, cooldown +
// charm-pet suppression, the same _fireTriggerActions dispatch that speaks the
// TTS and paints the overlay — but flagged as a rehearsal end to end. The #76
// rehearsal contract is the law here:
//   • every fire runs _fireTriggerActions(..., test=true) → NOTHING lands in
//     _fireLog, no relay, no Discord, no upload queue, no timeline capture;
//   • the REAL cooldown map (_triggerLastFire) is never touched — replay keeps
//     its own ephemeral cooldown map so the walk still SOUNDS like the fight
//     (a 30s-cooldown callout doesn't machine-gun) without consuming live
//     state;
//   • each fire is journalled with a `replay` marker + a ⏪ overlay tag so the
//     run is reviewable and nobody mistakes a replay callout for a live one.
// This is deliberately NOT a DVR: one replay at a time, refused while a live
// fight is in progress (same signal the update gate uses), bounded line cap.
const REPLAY_LINE_CAP    = 20000;   // most windowed trigger-visible lines we play
const REPLAY_MAX_GAP_MS  = 6000;    // real-time pacing caps idle gaps so lulls don't stall
const REPLAY_FAST_GAP_MS = 550;     // fast pacing: fixed pause AFTER a fire so each TTS is audible
const _sleep = (ms) => new Promise((r) => setTimeout(r, Math.max(0, ms | 0)));

// Live-fight signal — mirrors the fight branch of _updateBlockedReason() so a
// replay can't fire ⏪ callouts on top of a real fight's live callouts.
function _liveFightActive() {
  const et = stats.currentEncounterThreat;
  return !!(et && !et.flushedAt);
}

// Singleton replay status. `stop` is the cooperative-cancel flag the STOP
// button flips; the worker checks it between lines.
let _replayState = { running: false };

function _replayStateForWeb() {
  const st = _replayState;
  if (!st || !st.running && !st.done) return { running: false };
  return {
    running:   !!st.running,
    done:      !!st.done,
    stopped:   !!st.stop,
    pace:      st.pace || 'real',
    logLabel:  st.logLabel || null,
    scanned:   st.scanned || 0,
    total:     st.total || 0,
    played:    st.played || 0,
    fired:     st.fired || 0,
    error:     st.error || null,
    startedAt: st.startedAt || 0,
  };
}

// Per-line replay evaluator — a rehearsal-flavoured evaluateTriggersAgainstLine.
// Drives EACH matching trigger through pattern exec → charm-pet suppression →
// cooldown (against the local ctx map, NOT _triggerLastFire) → the real action
// dispatch as a rehearsal. Returns true if any trigger fired on this line.
function _replayEvaluateLine(line, tsMs, ctx) {
  const all = [..._personalTriggers, ...(stats.guildTriggers || [])];
  if (all.length === 0) return false;
  let firedAny = false;
  for (const t of all) {
    if (!t._regex) continue;   // gauge-condition triggers have no log line to replay
    let m;
    try { m = t._regex.exec(line); } catch { continue; }
    if (!m) continue;
    // Same guard + bag as the live evaluator — rehearsal must match live.
    if (t._conditions && t._conditions.length && !_captureConditionsPass(t._conditions, m.groups)) continue;
    const captures = _buildCaptureBag(m, line, {}, t._aliases);
    // Suppression — mirror the live pipeline (evaluate AND enforce), journalled
    // as a replay row so a swallowed callout is visible in the checkpoint log.
    if (_captureMatchesCharmPet(captures)) {
      _journalTrigger({ trigger: t.name, scope: 'replay', checkpoint: TJ.MATCHED,
                        stopped: true, replay: true,
                        reason: 'replay — suppressed (capture is your charm pet)' });
      continue;
    }
    // Cooldown — evaluated against the ephemeral REPLAY map so the walk is
    // faithful, but the real _triggerLastFire is never read or written.
    if (t.cooldown_seconds && t.cooldown_seconds > 0) {
      const key  = t.id || t.name;
      const last = ctx.cooldowns.get(key) || 0;
      if (tsMs - last < t.cooldown_seconds * 1000) {
        _journalTrigger({ trigger: t.name, scope: 'replay', checkpoint: TJ.GATES,
                          stopped: true, replay: true,
                          reason: 'replay — on cooldown (' + Math.ceil((t.cooldown_seconds * 1000 - (tsMs - last)) / 1000) + 's left)' });
        continue;
      }
      ctx.cooldowns.set(key, tsMs);
    }
    // Dispatch the action tail through the SAME handler a live fire uses, marked
    // test=true (no _fireLog/relay/upload) + _rehearsal + _replay (⏪ overlay,
    // spoken). _noJournal suppresses the handler's own row — we write one below.
    const rt = Object.assign({}, t, { _scope: 'replay', _rehearsal: true, _replay: true, _noJournal: true });
    _fireTriggerActions(rt, captures, tsMs, true);
    _journalTrigger({ trigger: t.name, scope: 'replay', checkpoint: TJ.DISPATCHED,
                      stopped: false, rehearsal: true, replay: true,
                      reason: 'replay — fired (rehearsal; cooldown local, live state untouched)' });
    firedAny = true;
  }
  return firedAny;
}

// Background worker: collect the windowed, trigger-visible lines, then play
// them back at the requested pace. Updates _replayState as it goes; the
// dashboard reads that via /api/state.
async function _replayWorker(st) {
  // 1. Collect. Read from byte 0, keep only lines whose parsed timestamp falls
  //    in [fromMs, toMs] AND pass triggerVisibleLine() (exactly the live tail's
  //    trigger gate). Stop early once we've walked past the window — logs are
  //    chronological, so there's no reason to read the rest of a huge file.
  const lines = [];
  let past = false;
  let lastTs = null;
  let scanned = 0;
  await readFromBytePos(st.logPath, 0,
    (raw) => {
      const d = parseEqTimestamp(raw);
      if (d) lastTs = d.getTime();
      const tsMs = d ? d.getTime() : lastTs;   // lines without their own stamp inherit the last one
      if (tsMs == null) return;
      if (tsMs < st.fromMs) return;
      if (tsMs > st.toMs) { past = true; return; }
      scanned++;
      if (triggerVisibleLine(raw) && lines.length < REPLAY_LINE_CAP) {
        lines.push({ raw, tsMs });
      }
    },
    null,
    () => past || st.stop || lines.length >= REPLAY_LINE_CAP,
  );
  st.scanned = scanned;
  st.total   = lines.length;
  scheduleRender();

  // 2. Paced playback through the rehearsal evaluator.
  const ctx = { cooldowns: new Map() };
  let prevTs = null;
  for (let i = 0; i < lines.length; i++) {
    if (st.stop) break;
    const { raw, tsMs } = lines[i];
    // Real-time: wait the true gap since the previous PLAYED line (capped so a
    // long lull compresses). Fast: no pre-gap — the pause rides AFTER a fire.
    if (i > 0 && st.pace === 'real') {
      const gap = Math.max(0, Math.min(REPLAY_MAX_GAP_MS, tsMs - (prevTs != null ? prevTs : tsMs)));
      if (gap > 0) await _sleep(gap);
      if (st.stop) break;
    }
    const fired = _replayEvaluateLine(raw, tsMs, ctx);
    st.played = i + 1;
    if (fired) {
      st.fired++;
      scheduleRender();
      if (st.pace === 'fast') await _sleep(REPLAY_FAST_GAP_MS);
    }
    prevTs = tsMs;
  }
  st.done    = true;
  st.running = false;
  // Now that replayed timers arm on the wall clock (see _startTimer), a long
  // replay can end with a stack of rehearsal countdowns still ticking. Sweep
  // every test-marked timer on completion — same rule as the dashboard's
  // testOnly clear — so a finished rehearsal leaves the overlay clean.
  for (const [id, t] of _activeTimers) {
    if (t.test) _activeTimers.delete(id);
  }
  scheduleRender();
}

// Start a replay. Synchronous guards (single-instance + live-fight refusal +
// path/time validation) run BEFORE any await so a second call races cleanly;
// the actual walk runs detached. Returns { ok, ... } for the HTTP route; the
// worker promise is stashed on st._done for the test fixture to await.
function startReplay(opts) {
  opts = opts || {};
  if (_replayState.running) {
    return { ok: false, error: 'A replay is already running — stop it first.' };
  }
  if (_liveFightActive()) {
    return { ok: false, error: 'A live fight is in progress — replay is blocked so it can\'t be mistaken for a live callout. Try again after the fight.' };
  }
  const logPath = String(opts.logPath || '');
  // Only replay a KNOWN log — the dashboard is localhost, but we still refuse
  // arbitrary filesystem reads: the path must be one the agent already watches.
  const known = (stats.watchedLogs || []).find((w) => w && w.logPath === logPath);
  if (!known) {
    return { ok: false, error: 'Unknown log file — pick one of the watched logs.' };
  }
  const fromMs = Number(opts.fromMs);
  const toMs   = Number(opts.toMs);
  if (!Number.isFinite(fromMs) || !Number.isFinite(toMs) || !(toMs > fromMs)) {
    return { ok: false, error: 'Bad time range — "to" must be after "from".' };
  }
  const pace = opts.pace === 'fast' ? 'fast' : 'real';
  const st = {
    running: true, stop: false, done: false, error: null,
    logPath, logLabel: known.character || logPath, fromMs, toMs, pace,
    startedAt: Date.now(), scanned: 0, total: 0, played: 0, fired: 0,
  };
  _replayState = st;
  st._done = _replayWorker(st).catch((err) => {
    st.error = String((err && err.message) || err);
    st.running = false;
    st.done = true;
    scheduleRender();
  });
  scheduleRender();
  return { ok: true, started: true, pace };
}

function stopReplay() {
  if (!_replayState || !_replayState.running) return { ok: true, stopped: false };
  _replayState.stop = true;
  return { ok: true, stopped: true };
}

// Transition a single backfill request via the bot's
// POST /api/agent/backfill-requests/{id}/{action} endpoint. `body` is the
// optional payload (reason / summary / error_message depending on action).
// Returns a Promise that resolves to true on success.
function postBackfillRequestAction({ botUrl, token, id, action, body }) {
  if (!botUrl || !token || !id || !action) return Promise.resolve(false);
  const base = botUrl.replace(/\/encounter(\?.*)?$/, '/backfill-requests');
  const url  = `${base}/${encodeURIComponent(id)}/${encodeURIComponent(action)}`;
  const json = body ? JSON.stringify(body) : '';
  return new Promise((resolve) => {
    try {
      const u = new URL(url);
      const mod = u.protocol === 'https:' ? https : http;
      const req = mod.request({
        method:   'POST',
        hostname: u.hostname,
        port:     u.port,
        path:     u.pathname,
        headers: {
          'Authorization': 'Bearer ' + token,
          'Content-Type':  'application/json',
          'Content-Length': Buffer.byteLength(json),
          'User-Agent':    `wolfpack-logsync/${AGENT_VERSION}`,
        },
        timeout: 5000,
      }, (res) => {
        res.on('data', () => {});
        res.on('end', () => resolve(res.statusCode >= 200 && res.statusCode < 300));
      });
      req.on('error',   () => resolve(false));
      req.on('timeout', () => { req.destroy(); resolve(false); });
      if (json) req.write(json);
      req.end();
    } catch { resolve(false); }
  });
}

function uploadHistoricalChat(messages, { botUrl, token, dryRun }) {
  void botUrl; void token;
  if (dryRun) {
    console.log(`[historical-chat] ${messages.length} chat lines (dry-run)`);
    return Promise.resolve({ stored: messages.length });
  }
  enqueueUpload('historical_chat', { agent_version: AGENT_VERSION, messages });
  return Promise.resolve({ stored: messages.length });
}

function uploadLockouts(entries, { botUrl, token, dryRun, character }) {
  void botUrl; void token;
  // Attach the character name so the bot can store it as killedBy
  const enriched = entries.map(e => ({ ...e, character: character || 'unknown' }));
  if (dryRun) {
    for (const e of enriched)
      console.log(`[lockout] ${e.bossName}: ${Math.round(e.remainingMs / 3600000)}h remaining`);
    return Promise.resolve();
  }
  enqueueUpload('lockout', { agent_version: AGENT_VERSION, entries: enriched });
  return Promise.resolve();
}

// Faction events upload → bot's /api/agent/faction. Two kinds ride the same
// payload: 'hit' (a "Your faction standing with X got better/worse" line,
// incl. the at-cap forms) and 'con' (a /consider standing TRANSITION for a
// mob). Bot-side unique constraints make backfill replays idempotent, so
// crawling a complete log history is safe to re-run.
function uploadPopFlags(events, { dryRun } = {}) {
  if (!Array.isArray(events) || events.length === 0) return Promise.resolve();
  if (dryRun) {
    for (const e of events) console.log(`[pop-flag] ${e.character} · ${e.source || 'event'}${e.npc ? ' → ' + e.npc : ''} · ${e.zone || '?'} · ${e.boss || '?'} · ${e.ts}`);
    return Promise.resolve();
  }
  enqueueUpload('pop_flag', { agent_version: AGENT_VERSION, events });
  return Promise.resolve();
}

function uploadFaction(events, { dryRun } = {}) {
  if (!Array.isArray(events) || events.length === 0) return Promise.resolve();
  if (dryRun) {
    for (const e of events) console.log(`[faction] ${e.kind} · ${e.character} · ${e.faction || e.mob} · ${e.direction != null ? (e.direction > 0 ? 'better' : 'worse') : e.standing} · ${e.ts}`);
    return Promise.resolve();
  }
  // CHUNK the payload. Live flushes carry a handful of events, but a
  // complete-log backfill accumulates the whole history in factionBuffer and
  // drains it ONCE at the end — a heavy character's multi-year crawl is
  // 50k+ hit events (~7MB JSON), which would blow the bot endpoint's 512KB
  // body cap (413 → the queue retries a permanently-oversized payload) and
  // bloat logsync.queue.json. 1,500 events ≈ 200KB — comfortable margin.
  const CHUNK = 1500;
  for (let i = 0; i < events.length; i += CHUNK) {
    enqueueUpload('faction', { agent_version: AGENT_VERSION, events: events.slice(i, i + CHUNK) });
  }
  return Promise.resolve();
}

// Fun-events upload (Peopleslayer LD counter, future CoH/DI/Aegolism). Each
// event is a tagged occurrence the bot stores in the fun_events table with
// a unique constraint on (guild_id, event_type, caster, event_ts) so re-
// running the same backfill doesn't double-count. See utils/state and the
// fun_events Supabase migration on the bot side.
function uploadFunEvents(events, { dryRun } = {}) {
  if (!Array.isArray(events) || events.length === 0) return Promise.resolve();
  if (dryRun) {
    for (const e of events) console.log(`[fun-event] ${e.type} · ${e.caster || ''} · ${e.ts}`);
    return Promise.resolve();
  }
  enqueueUpload('fun_event', { agent_version: AGENT_VERSION, events });
  return Promise.resolve();
}

// Observed buff landings on other players → bot's /api/agent/buff_casts. The
// bot dedups across observers, so every nearby agent uploading what it saw is
// fine (and desirable — more observers = better coverage).
function uploadBuffCasts(casts, { dryRun } = {}) {
  if (!Array.isArray(casts)) return Promise.resolve();
  // Nameless (unresolved-ambiguous) landings stay useful LOCALLY (Mob Info
  // shows the raw landing text), but every bot-side consumer requires a
  // spell_name — uploading them just grew buff_casts (18% of the table before
  // the 2026-07-07 purge; the bot also rejects them at ingest now).
  casts = casts.filter(c => c && c.spell_name);
  if (casts.length === 0) return Promise.resolve();
  if (dryRun) {
    for (const c of casts) console.log(`[buff-cast] ${c.target} ← ${c.spell_name || '(ambiguous: ' + c.landing_text + ')'} @ ${c.cast_at}`);
    return Promise.resolve();
  }
  // #72 P1b: ordinary observed landings are ZONE-redundant — every same-zone
  // agent sees the identical land — so only the elected buff reporter(s) upload
  // them; non-reporters drop them (a reporter in the zone still sends them).
  // CRITICAL exception: is_charm_spell rows are agent-SYNTHESIZED per-observer
  // facts (charm timers — no cast_on_other log line exists for other clients),
  // so they are NEVER gated and always ship. Fail-open: buffs role defaults TRUE
  // and RESETS to true on any poll failure, so a lost elector = upload everything
  // (same staleness rule the chat gate uses). Split the batch accordingly.
  if (!_reporterRoles.buffs) {
    casts = casts.filter(c => c.is_charm_spell);
    if (casts.length === 0) return Promise.resolve();
  }
  enqueueUpload('buff_cast', { agent_version: AGENT_VERSION, casts });
  return Promise.resolve();
}

// Inbound /tell relay. The bot endpoint re-validates characters.tell_relay
// before accepting, so this is a safe defense-in-depth — but the agent also
// gates on stats.characterPrefs[character].tell_relay so we don't burn the
// queue with rejected uploads.
function uploadTells({ character, tells }, { dryRun } = {}) {
  if (!character || !Array.isArray(tells) || tells.length === 0) return Promise.resolve();
  if (dryRun) {
    for (const t of tells) console.log(`[tell:${t.direction}] ${character} ${t.direction === 'outgoing' ? '→' : '←'} ${t.other}: ${t.text}`);
    return Promise.resolve();
  }
  // dm_pause_until: a per-machine "pause Discord tells" set from the Mimic
  // tray. The bot still STORES the tells (so /me/tells + the local card stay
  // current) but skips the Discord DM while the pause is in the future.
  const dmPauseUntil = (_tellsDmPauseUntil && _tellsDmPauseUntil > Date.now()) ? _tellsDmPauseUntil : undefined;
  enqueueUpload('tells', { agent_version: AGENT_VERSION, character, tells, dm_pause_until: dmPauseUntil });
  return Promise.resolve();
}

// ── File watcher (tail mode) ────────────────────────────────────────────────
// Polls every 500ms. Uses fs.stat to detect size growth. Reads only NEW bytes.
// Handles file rotation (size goes down → start from 0) and Windows line endings.

async function tailFile(logPath, onLine) {
  let stat;
  try { stat = await fs.promises.stat(logPath); }
  catch (err) { throw new Error(`Cannot stat ${logPath}: ${err.message}`); }

  let pos = stat.size;
  let buf = '';
  if (!_dashboardEnabled) {
    console.log(`[${path.basename(logPath)}] tailing from offset ${pos} (file size ${stat.size})`);
  }

  setInterval(async () => {
    try {
      const s = await fs.promises.stat(logPath);
      if (s.size < pos) {
        // File rotated/truncated — start from new top
        console.log(`[${path.basename(logPath)}] file rotated; resetting position`);
        pos = 0;
        buf = '';
      }
      if (s.size > pos) {
        const fd = await fs.promises.open(logPath, 'r');
        const len = s.size - pos;
        const data = Buffer.alloc(len);
        await fd.read(data, 0, len, pos);
        await fd.close();
        buf += data.toString('utf8');
        const lines = buf.split(/\r?\n/);
        buf = lines.pop() || '';
        for (const line of lines) if (line) onLine(line);
        pos = s.size;
      }
    } catch (err) {
      console.warn(`[tail] ${err.message}`);
    }
  }, 500);
}

// ── Log rotation (feedback: Ashieron 2026-08-07) ────────────────────────────
// "Keep track of logfile size and cull the file when it gets too big, or keep
// it at a maximum size and file old logs to another location." We do the
// second, never the first: old logs are the raw material for --since backfill,
// historical chat, and parse re-runs, so culling would destroy the guild's own
// history. A live log over the threshold is RENAMED into LogArchive/ next to
// the logs and an empty file is recreated in its place, which the tailer's
// existing size<pos rotation handling picks up as a reset.
//
// Safety model, in order:
//   1. mtime idle gate — we only touch a file quiet for LOG_ROTATE_IDLE_MS
//      (not being written = the character is not playing).
//   2. The OS is the real gate: Windows refuses to rename a file EQ holds
//      open (no FILE_SHARE_DELETE on its append handle), so a racing EQ
//      session makes the rename fail cleanly and we just skip this sweep.
//   3. Same-directory rename — atomic, instant, no copy, no disk double-use.
// WP_LOG_ROTATE_MB=0 disables; default 500MB (Hitya 2026-08-07), default ON.
// Idle default 15 min.
const LOG_ROTATE_MB      = (() => { const v = parseInt(process.env.WP_LOG_ROTATE_MB, 10); return Number.isFinite(v) ? v : 500; })();
const LOG_ROTATE_IDLE_MS = Math.max(60_000, (parseInt(process.env.WP_LOG_ROTATE_IDLE_MIN, 10) || 15) * 60_000);

// Pure decision — exercised directly by test/log-rotate.test.js.
function _shouldRotateLog(sizeBytes, mtimeMs, nowMs, thresholdMb, idleMs) {
  if (!(thresholdMb > 0)) return false;                       // feature off
  if (!(sizeBytes > thresholdMb * 1024 * 1024)) return false; // under the cap
  if (!(nowMs - mtimeMs >= idleMs)) return false;             // being written
  return true;
}

function _rotateArchiveName(logPath, nowMs) {
  const d = new Date(nowMs);
  const pad = (n) => String(n).padStart(2, '0');
  const stamp = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate())
              + '-' + pad(d.getHours()) + pad(d.getMinutes());
  return path.basename(logPath).replace(/\.txt$/i, '') + '.' + stamp + '.txt';
}

// Tiny persisted agent prefs (state dir, beside personal_triggers.json).
// First use: the dashboard's log-archiving off switch — env vars are not a
// reachable surface for Mimic users, so the opt-out has to live in a file.
let _agentPrefsCache = null;
function _agentPrefsPath() {
  const dir = path.dirname(STATS_FILE || '');
  return dir ? path.join(dir, 'logsync.prefs.json') : null;
}
function _agentPrefs() {
  if (_agentPrefsCache) return _agentPrefsCache;
  try {
    const p2 = _agentPrefsPath();
    _agentPrefsCache = (p2 && fs.existsSync(p2)) ? (JSON.parse(fs.readFileSync(p2, 'utf8')) || {}) : {};
  } catch { _agentPrefsCache = {}; }
  return _agentPrefsCache;
}
function _saveAgentPrefs(patch) {
  const merged = Object.assign({}, _agentPrefs(), patch || {});
  _agentPrefsCache = merged;
  try {
    const p2 = _agentPrefsPath();
    if (p2) fs.writeFileSync(p2, JSON.stringify(merged, null, 2));
  } catch (err) { console.warn('[prefs] save failed:', err.message); }
  return merged;
}
function _logRotateEnabled() {
  return LOG_ROTATE_MB > 0 && !_agentPrefs().log_rotate_off;
}
// Watched logs currently over the cap — the "these will be archived on the
// next quiet sweep" list for the dashboard banner. Size gate only (no idle
// check): the point is telling the user WHAT is impacted, not when.
function _logRotateCandidates() {
  const out = [];
  for (const w of (stats.watchedLogs || [])) {
    if (!w || !w.logPath) continue;
    try {
      const st = fs.statSync(w.logPath);
      if (st.size > LOG_ROTATE_MB * 1024 * 1024) {
        out.push({ file: path.basename(w.logPath), size_mb: Math.round(st.size / (1024 * 1024)) });
      }
    } catch { /* unreadable — skip */ }
  }
  return out;
}

async function _logRotateSweep() {
  if (!_logRotateEnabled()) return;
  const now = Date.now();
  for (const w of (stats.watchedLogs || [])) {
    if (!w || !w.logPath) continue;
    try {
      const st = await fs.promises.stat(w.logPath);
      if (!_shouldRotateLog(st.size, st.mtimeMs, now, LOG_ROTATE_MB, LOG_ROTATE_IDLE_MS)) continue;
      const dir = path.join(path.dirname(w.logPath), 'LogArchive');
      try { fs.mkdirSync(dir, { recursive: true }); } catch { /* exists */ }
      const dest = path.join(dir, _rotateArchiveName(w.logPath, now));
      fs.renameSync(w.logPath, dest);              // EQ holding it open → throws → skip
      try { fs.writeFileSync(w.logPath, '', { flag: 'wx' }); } catch { /* recreated by EQ */ }
      const mb = Math.round(st.size / (1024 * 1024));
      if (!Array.isArray(stats.logRotations)) stats.logRotations = [];
      stats.logRotations.unshift({ file: path.basename(w.logPath), dest, mb, at: new Date(now).toISOString() });
      if (stats.logRotations.length > 10) stats.logRotations.length = 10;
      console.log('[log-rotate] ' + path.basename(w.logPath) + ' (' + mb + 'MB) → ' + dest);
    } catch { /* stat failed or rename refused (EQ has it open) — next sweep */ }
  }
}

// ── Time-window mode (backfill) ─────────────────────────────────────────────
async function readWindow(logPath, since, until, onLine) {
  // For now, naive: stream the file line by line and only emit lines whose
  // timestamp falls within the window. A future optimization is binary-search
  // by stat to seek directly to the start of the window; for files <10GB and
  // backfill that's a once-in-a-while operation, this is fine.
  const stream = fs.createReadStream(logPath, { encoding: 'utf8', highWaterMark: 1 << 16 });
  let buf = '';
  return new Promise((resolve, reject) => {
    stream.on('data', chunk => {
      buf += chunk;
      const lines = buf.split(/\r?\n/);
      buf = lines.pop() || '';
      for (const line of lines) {
        const ts = parseEqTimestamp(line);
        if (!ts) continue;
        if (since && ts < since) continue;
        if (until && ts > until) {
          stream.destroy(); // stop early — we're past the window
          return;
        }
        onLine(line);
      }
    });
    stream.on('end', resolve);
    stream.on('close', resolve);
    stream.on('error', reject);
  });
}

// ── Main ────────────────────────────────────────────────────────────────────
async function main() {
  const args = parseArgs(process.argv);
  // Watch mode tolerates ZERO logs: run the dashboard + Zeal/state endpoints and
  // simply tail nothing until logs appear. Hard-failing here is what made Mimic
  // crash-loop for users whose EQ folder wasn't found OR who haven't enabled
  // in-game logging yet (Zeal can be flowing while there are no eqlog_* files).
  // The host (Mimic) restarts the agent once logs become available. --once /
  // --since still require logs — there's nothing to backfill without them.
  const _wantsWatch = args.flags.watch || (!args.flags.once && !args.flags.since);
  if (args.logs.length === 0 && !_wantsWatch) {
    console.error('❌ At least one --log is required. Use --help for usage.');
    process.exit(1);
  }
  if (args.logs.length === 0) {
    console.warn('⚠ No EQ log files to tail yet — running the dashboard only. Turn on in-game logging (/log on, and Logging=on in eqclient.ini) and/or set your EQ folder; logs are picked up automatically once they appear.');
  }

  // ── Single-instance check ─────────────────────────────────────────────────
  // If a background service is already running, don't double-tail the logs —
  // just point the user at the dashboard URL and exit. The check is skipped
  // when started with --no-service-check (so the service spawn itself works).
  if (!args.flags.noServiceCheck) {
    const active = readActivePid();
    if (active && active.pid !== process.pid) {
      const live = active.webPort ? await probeWebDashboard(active.webPort) : false;
      if (live) {
        const url = `http://localhost:${active.webPort}`;
        console.log(`\n  ${ANSI.green}✓ Service already running${ANSI.reset} (pid ${active.pid}, v${active.agentVersion}, since ${active.startedAt}).`);
        console.log(`  ${ANSI.cyan}Dashboard:${ANSI.reset} ${url}`);

        // Non-TTY (auto-restart, CI, redirected stdout) — open browser and
        // exit silently. TTY users get the prompt first; the browser is only
        // launched after they pick V (or the timeout defaults to V) so the
        // prompt isn't stolen by the OS focus-change to the browser window.
        if (!process.stdin.isTTY) {
          openDashboardInBrowser(active.webPort);
          process.exit(0);
        }

        console.log(`\n  ${ANSI.bold}What do you want to do?${ANSI.reset}`);
        console.log(`    ${ANSI.cyan}[V]${ANSI.reset} View dashboard, leave service running ${ANSI.dim}(default — auto-selects in 30s)${ANSI.reset}`);
        console.log(`    ${ANSI.cyan}[K]${ANSI.reset} Kill the service entirely`);
        console.log(`    ${ANSI.cyan}[R]${ANSI.reset} Kill the service and resume in this window`);
        console.log('');

        const choice = await new Promise((resolve) => {
          // 30s so the user has time to read the options without the browser
          // stealing focus mid-decision.
          const timer = setTimeout(() => resolve('v'), 30_000);
          try { process.stdin.setRawMode(true); } catch {}
          process.stdin.resume();
          process.stdin.setEncoding('utf8');
          const onData = (data) => {
            const k = data.toString().toLowerCase();
            if (k === 'v' || k === 'k' || k === 'r' || k === '\x03') {
              clearTimeout(timer);
              process.stdin.removeListener('data', onData);
              try { process.stdin.setRawMode(false); } catch {}
              resolve(k === '\x03' ? 'v' : k);
            }
          };
          process.stdin.on('data', onData);
        });

        if (choice === 'v') {
          // Now safe to open the browser — the user already made their pick.
          openDashboardInBrowser(active.webPort);
          console.log(`  ${ANSI.dim}Service kept running. Feel free to close this window.${ANSI.reset}\n`);
          process.exit(0);
        }

        // K or R: ask the service to shut down cleanly via /api/shutdown
        console.log(`  ${ANSI.yellow}Asking service (pid ${active.pid}) to shut down...${ANSI.reset}`);
        const shutdownOk = await new Promise((resolve) => {
          const req = http.request({
            hostname: '127.0.0.1', port: active.webPort, path: '/api/shutdown',
            method: 'POST', timeout: 3000,
          }, (res) => { res.resume(); resolve(res.statusCode === 200); });
          req.on('error',   () => resolve(false));
          req.on('timeout', () => { req.destroy(); resolve(false); });
          req.end();
        });
        if (!shutdownOk) {
          // Fallback: force-kill the PID
          console.log(`  ${ANSI.dim}Shutdown endpoint didn't respond — force-killing pid ${active.pid}${ANSI.reset}`);
          try { process.kill(active.pid, 'SIGTERM'); } catch {}
          // Give the OS a moment, then SIGKILL if still alive
          await new Promise(r => setTimeout(r, 1500));
          try { process.kill(active.pid, 0); try { process.kill(active.pid, 'SIGKILL'); } catch {} } catch {}
        }
        // Wait for PID to actually exit (max 5s)
        for (let i = 0; i < 25; i++) {
          try { process.kill(active.pid, 0); }
          catch { break; }   // process gone
          await new Promise(r => setTimeout(r, 200));
        }
        removePidFile();
        console.log(`  ${ANSI.green}✓ Service stopped.${ANSI.reset}`);

        if (choice === 'k') {
          console.log(`  ${ANSI.dim}This window will close now.${ANSI.reset}\n`);
          process.exit(0);
        }
        // choice === 'r': fall through and continue normal startup —
        // loadSessionState() will pick up where the killed service left off.
        console.log(`  ${ANSI.cyan}Resuming agent in this window...${ANSI.reset}\n`);
      } else {
        // PID exists but web dashboard isn't responding — stale, clean it up
        removePidFile();
      }
    }

    // ── Port-probe fallback ────────────────────────────────────────────────
    // Older agent versions (pre-v2.3.20) didn't write a PID file, so the
    // check above won't detect them. Probe the default web port directly —
    // if SOMETHING is serving /api/state on 127.0.0.1:7777, assume it's an
    // ancient agent and offer the same V/K/R prompt so we don't end up with
    // two processes silently fighting for the port.
    if (!args.flags.noServiceCheck) {
      const probePort = args.flags.webPort || 7777;
      const probeLive = await probeWebDashboard(probePort);
      if (probeLive) {
        const url = `http://localhost:${probePort}`;
        console.log(`\n  ${ANSI.yellow}⚠ Another agent is already serving ${url}${ANSI.reset}`);
        console.log(`  ${ANSI.dim}(No PID file — likely an older version that didn't write one.)${ANSI.reset}`);
        if (!process.stdin.isTTY) {
          openDashboardInBrowser(probePort);
          process.exit(0);
        }
        console.log(`\n  ${ANSI.bold}What do you want to do?${ANSI.reset}`);
        console.log(`    ${ANSI.cyan}[V]${ANSI.reset} View dashboard, leave it running ${ANSI.dim}(default — auto in 30s)${ANSI.reset}`);
        console.log(`    ${ANSI.cyan}[K]${ANSI.reset} Kill it (asks via /api/shutdown, falls back to manual)`);
        console.log(`    ${ANSI.cyan}[R]${ANSI.reset} Kill it and resume in this window\n`);
        const choice = await new Promise((resolve) => {
          const timer = setTimeout(() => resolve('v'), 30_000);
          try { process.stdin.setRawMode(true); } catch {}
          process.stdin.resume();
          process.stdin.setEncoding('utf8');
          const onData = (data) => {
            const k = data.toString().toLowerCase();
            if (k === 'v' || k === 'k' || k === 'r' || k === '\x03') {
              clearTimeout(timer);
              process.stdin.removeListener('data', onData);
              try { process.stdin.setRawMode(false); } catch {}
              resolve(k === '\x03' ? 'v' : k);
            }
          };
          process.stdin.on('data', onData);
        });
        if (choice === 'v') {
          openDashboardInBrowser(probePort);
          console.log(`  ${ANSI.dim}Other service kept running. Closing this window.${ANSI.reset}\n`);
          process.exit(0);
        }
        // Try graceful shutdown via /api/shutdown
        console.log(`  ${ANSI.yellow}Asking the other agent to shut down...${ANSI.reset}`);
        const shutdownOk = await new Promise((resolve) => {
          const req = http.request({
            hostname: '127.0.0.1', port: probePort, path: '/api/shutdown',
            method: 'POST', timeout: 3000,
          }, (res) => { res.resume(); resolve(res.statusCode === 200); });
          req.on('error',   () => resolve(false));
          req.on('timeout', () => { req.destroy(); resolve(false); });
          req.end();
        });
        if (!shutdownOk) {
          console.log(`  ${ANSI.red}✗ The other agent doesn't have /api/shutdown (likely too old).${ANSI.reset}`);
          console.log(`  ${ANSI.dim}Find the PID with:   netstat -ano | findstr :${probePort}${ANSI.reset}`);
          console.log(`  ${ANSI.dim}Kill it with:        taskkill /F /PID <pid>${ANSI.reset}`);
          console.log(`  ${ANSI.dim}Then re-run parser.bat.${ANSI.reset}\n`);
          process.exit(0);
        }
        // Wait for port to free up
        for (let i = 0; i < 25; i++) {
          if (!(await probeWebDashboard(probePort))) break;
          await new Promise(r => setTimeout(r, 200));
        }
        console.log(`  ${ANSI.green}✓ Other agent stopped.${ANSI.reset}`);
        if (choice === 'k') {
          console.log(`  ${ANSI.dim}This window will close now.${ANSI.reset}\n`);
          process.exit(0);
        }
        console.log(`  ${ANSI.cyan}Resuming agent in this window...${ANSI.reset}\n`);
      }
    }
  }

  // Load optional config (custom drop patterns, etc.)
  let dropPatterns = DEFAULT_DROP_PATTERNS;
  let keepPatterns = KEEP_PATTERNS;
  if (args.flags.config) {
    try {
      const cfg = JSON.parse(fs.readFileSync(args.flags.config, 'utf8'));
      if (cfg.drop_patterns) dropPatterns = cfg.drop_patterns.map(s => new RegExp(s, 'i'));
      if (cfg.keep_patterns) keepPatterns = cfg.keep_patterns.map(s => new RegExp(s, 'i'));
      console.log(`Loaded config from ${args.flags.config}`);
    } catch (err) {
      console.error(`Failed to load config: ${err.message}`);
      process.exit(1);
    }
  }

  const botUrl = args.flags.botUrl || DEFAULT_BOT_URL;
  const token  = args.flags.token  || process.env.WOLFPACK_TOKEN || null;
  const dryRun = args.flags.dryRun;

  if (!dryRun && !token) {
    console.warn('⚠️  No --token / WOLFPACK_TOKEN set. Uploads will likely fail auth.');
  }

  // Make opts available to the chat relay flush (module-level so the interval can see them)
  _uploadOpts    = { botUrl, token, dryRun };
  _isServiceMode = !!args.flags.noServiceCheck;

  // Spell catalog: load any cached copy from disk synchronously so the first
  // dashboard render has spell names + PQDI ids, then fire a background fetch
  // to refresh from the bot. We don't await — a slow fetch must not delay
  // boot, and the resisted-spell card just shows plain names until it lands.
  _loadSpellCatalogFromDisk();
  _loadItemClickiesFromDisk();
  loadItemCatalogFromDisk();
  // Restore the Pet tracker's in-memory state (last /pet health, observed buff
  // landings, running combat stats) so a Mimic restart or LD reconnect brings
  // the existing pet timers + stats back instead of starting blank. TTLs in
  // the loader drop entries old enough to be stale.
  _loadPetStateFromDisk();
  if (!dryRun && token) {
    fetchSpellCatalog({ botUrl, token }).catch(() => {});
    fetchItemClickies({ botUrl, token }).catch(() => {});
    fetchItemCatalog({ botUrl, token }).catch(() => {});
    startReporterHeartbeat();   // #72 — poll the bot for our upload roles (fail-open)
    setInterval(() => { try { uploadRollSets(); } catch {} }, 60_000).unref();   // #91 off-night roll capture
    setInterval(() => { try { uploadLooted(); } catch {} }, 60_000).unref();     // #91 looted-line capture
    // Re-fetch daily — the catalog only changes on the weekly upstream sync,
    // but a daily check is cheap (the bot serves a 304 if nothing changed)
    // and stops a long-running agent from drifting indefinitely.
    setInterval(() => {
      fetchSpellCatalog({ botUrl, token }).catch(() => {});
      fetchItemClickies({ botUrl, token }).catch(() => {});
      fetchItemCatalog({ botUrl, token }).catch(() => {});
    }, 24 * 60 * 60 * 1000).unref();
  }
  // Operator's declared main (if the launcher passed --character) — used to
  // attribute operator-level uploads instead of "(unknown)".
  _primaryCharacterOverride = args.flags.character || null;

  // Elect the single machine-wide uploader BEFORE the queue drain kicks, so a
  // read-only instance (another Parser/Mimic already uploading) doesn't replay
  // its queue or send live data. dry-run never uploads, so skip the election.
  if (!dryRun) startUploaderElection(args.flags.webPort);

  // Start the durable upload queue drain. Loads any pending entries from
  // disk first and kicks an immediate replay attempt — so anything left
  // over from a previous crashed session goes out as soon as the
  // network's back.
  if (!dryRun) startUploadQueueDrain({ botUrl, token });

  // Load persisted lifetime stats so the dashboard can show them
  loadStats();
  // Restore in-flight session state if the previous run snapshotted within the
  // last 10 minutes (typical for [U] update-and-restart, or quick Ctrl+C).
  const _sessionRestored = loadSessionState();
  if (_sessionRestored) {
    stats._sessionRestoredBanner = true;
    stats._sessionRestoredAt     = Date.now();
  }

  // Inventory scan — pick up any <Char>-Inventory.txt files in the log dir
  // so tanks' weapon loadouts can be surfaced + (Phase 2) cross-referenced
  // against a proc database for theoretical TPS.
  refreshInventories();
  setInterval(refreshInventories, 5 * 60_000);

  // Quarmy export ingest — <Name>Quarmy.txt in the same dir (the file
  // members generate for quarmy.com). Parsed locally; bank/sharedbank/coin
  // rows are dropped at parse and never leave the machine. The scan no-ops
  // until the character-prefs poll has answered once (exclude_inventory must
  // be known, not assumed), so the first useful pass is the 30s one.
  setTimeout(scanQuarmyExports, 30_000);
  setInterval(scanQuarmyExports, 10 * 60_000);
  // Settings-file safety net — 60s after boot (watched logs resolved by then,
  // and off the boot hot path) + every 6h. Content-hash gated, so quiet when
  // nothing changed.
  setTimeout(backupSettingsFiles, 60_000);
  setInterval(backupSettingsFiles, 6 * 3600_000);

  // Spellbook export ingest — <Char>-Spellbook.txt from EQ's /outputfile
  // spellbook, same dir + same prefs gate as Quarmy. Keeps the /character
  // "missing spells" page current with no manual paste.
  setTimeout(scanSpellbookFiles, 35_000);
  setInterval(scanSpellbookFiles, 10 * 60_000);

  // Inventory export ingest — <Char>-Inventory.txt, the third sibling. The
  // bot endpoint existed since June; this scan is the half that was missing
  // (2026-08-20, the invisible Ancient scrolls). Same prefs gate + cadence.
  setTimeout(scanInventoryUploads, 40_000);
  setInterval(scanInventoryUploads, 10 * 60_000);

  // Version polling — reach out to the bot every 10 min so idle agents
  // still learn about new releases promptly (without needing an encounter
  // upload to surface latest_agent_version).
  if (botUrl) {
    pollLatestVersion({ botUrl });
    setInterval(() => pollLatestVersion({ botUrl }), 10 * 60_000);
    // Officer-filed backfill request poll. Runs slightly more often than the
    // version probe since requests are actionable (officers expect agents to
    // notice within ~5 min). Initial run is delayed a few seconds so the
    // log-tail enumeration has populated stats.watchedLogs first.
    setTimeout(() => pollBackfillRequests({ botUrl, token }), 8_000);
    setInterval(() => pollBackfillRequests({ botUrl, token }), 5 * 60_000);
    // Guild triggers: load on startup (after watchedLogs is populated) and
    // refresh every 10 min. Personal triggers load once from local disk.
    loadPersonalTriggers();
    setTimeout(() => pollGuildTriggers({ botUrl, token }), 12_000);
    // Poll every 2 min so a newly added/edited guild trigger reaches raiders in
    // ~2 min instead of 10. Cheap: the version-gate above skips the recompile
    // when nothing changed, and the set is small (a few KB).
    setInterval(() => pollGuildTriggers({ botUrl, token }), 2 * 60_000);
    // Per-character data prefs (exclude_from_stats / exclude_inventory).
    // Polled so the owner's choice on /me takes effect within ~10 min on every
    // machine they run the agent on — no agent restart required.
    setTimeout(() => pollCharacterPrefs({ botUrl, token }), 10_000);
    setInterval(() => pollCharacterPrefs({ botUrl, token }), 10 * 60_000);
    // Remote overlay tuning (officer knob overrides from /admin/overlays).
    // 90s so a mid-raid threshold tweak lands on every Mimic within ~1.5 min.
    setTimeout(() => pollOverlayTuning({ botUrl, token }), 6_000);
    setInterval(() => pollOverlayTuning({ botUrl, token }), 90_000);
    // Web-staged macro edits (/me/ui) — applied only while the character is
    // logged out; 5 min poll keeps "staged on the web → on my hotbar next
    // session" comfortably true without hammering anything.
    setTimeout(() => pollUiPendingEdits({ botUrl, token }), 25_000);
    setInterval(() => pollUiPendingEdits({ botUrl, token }), 5 * 60_000);
    // Live character state (buffs + last-seen zone) → bot → Supabase so
    // wolfpack.quest/me can show what each character is carrying + where, AND
    // (Hitya 2026-07-03: "Debuff queue definitely needs to be faster") this
    // is the PRIMARY latency source for a newly-landed curse showing up on
    // anyone's debuff queue — this interval is how often a cursed player's own
    // agent even CHECKS whether their buff set changed, before the bot ever
    // hears about it; the buff-queue read-side cache (BUFF_QUEUE_TTL_MS) is a
    // much smaller contributor on top of whatever this interval already cost.
    // Was 20s (worst case ~20s just to detect the change, before the queue's
    // own cache/poll latency even starts); tightened to 5s. Still cheap — the
    // signature check below only actually POSTs on a real change, so a
    // shorter interval mostly just means "notice sooner", not "send more".
    setInterval(() => { try { flushLiveStateToBot({ botUrl, token }); } catch {} }, 5_000);
    // Opt-in crash telemetry: scan the EQ folder's Zeal crashes/ dir for new
    // bundles. Gated on WOLFPACK_CRASH_REPORTS=1 (Mimic tray toggle) — never
    // runs otherwise. 60s cadence; startup scan delayed so watchedLogs (the
    // EQ-dir source) is populated.
    if (CRASH_REPORTS_ENABLED) {
      setTimeout(() => { try { scanCrashDirs(); } catch {} }, 15_000);
      setInterval(() => { try { scanCrashDirs(); } catch {} }, 60_000);
    }
  }

  // Optional web dashboard — bind 127.0.0.1 only, single HTML page polls /api/state.
  if (args.flags.webPort) {
    startWebDashboard(args.flags.webPort);
    writePidFile(args.flags.webPort);
    // Best-effort cleanup so a stale PID doesn't block the next launch.
    // Queue-flush exit handlers are registered separately by
    // startUploadQueueDrain() so they fire even in non-dashboard CLI mode.
    process.on('exit',    () => removePidFile());
    process.on('SIGINT',  () => { removePidFile(); process.exit(0); });
    process.on('SIGTERM', () => { removePidFile(); process.exit(0); });
    // Auto-open the browser on FRESH starts only — skip if we just resumed
    // (i.e. this is a [U] auto-restart or quick Ctrl+C relaunch). Also skip
    // when --no-auto-open is set for headless / CI scenarios, AND when running
    // under Mimic (WOLFPACK_CLIENT=mimic) — the Electron window already shows
    // the dashboard, so popping the external browser on every startup was just
    // noise. Parser.bat users still get the browser (it's their only UI).
    const _underMimic = process.env.WOLFPACK_CLIENT === 'mimic';
    if (!_sessionRestored && !args.flags.noAutoOpen && !_underMimic) {
      // Small delay so the listener has bound and the page returns 200
      setTimeout(() => openDashboardInBrowser(args.flags.webPort), 800);
    }
  }
  // Backstop save every 60s so a hard crash loses at most a minute.
  setInterval(() => {
    if (stats.sessionEvents > 0 || stats.uploadCount > 0) {
      try { saveSessionState(); } catch {}
    }
  }, 60_000);

  // Per-character "do not transmit" list. Set by the user from Mimic
  // (onboarding + Settings) for characters they don't want any data uploaded
  // about — typically friends' boxes that play in other guilds, alts they
  // share data on, etc. Enforced at the OUTERMOST boundary: an excluded
  // character's log file is never opened, never tailed, never registered as a
  // watchedLog. Nothing about that character can ever leave the machine,
  // regardless of how many downstream code paths the agent grows. Case-
  // insensitive match on the canonical (filename-derived) character name.
  const excludedCsv = process.env.WOLFPACK_EXCLUDED_CHARS || '';
  const excludedSet = new Set(
    excludedCsv.split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
  );
  if (excludedSet.size > 0) {
    console.log(`[exclude] not transmitting for: ${[...excludedSet].join(', ')}`);
  }
  const allLogs    = args.logs;
  const filtered   = [];
  const droppedFor = [];
  const droppedBackups = [];
  for (const p of allLogs) {
    const fromName = characterFromFilename(p) || '';
    if (fromName && excludedSet.has(fromName.toLowerCase())) {
      droppedFor.push(fromName);
      continue;
    }
    // Never LIVE-TAIL a copied-aside backup. Now that eqlog_Dant3 resolves to
    // "Dant", tailing it alongside the real eqlog_Dant would replay the same
    // events a second time under one name — turning a phantom extra raider
    // into a doubled real one, which is strictly worse. Backups stay visible
    // for BACKFILL (that is what they are good for); they just never join the
    // live stream.
    if (isBackupLogFile(p)) {
      droppedBackups.push(path.basename(p));
      continue;
    }
    filtered.push(p);
  }
  if (droppedBackups.length > 0) {
    console.log(`[logs] skipped ${droppedBackups.length} backup log file(s) — copied aside, not live: ${droppedBackups.join(', ')}`);
  }
  if (droppedFor.length > 0) {
    console.log(`[exclude] dropped ${droppedFor.length} log file(s) for excluded characters: ${droppedFor.join(', ')}`);
  }
  args.logs = filtered;

  // One encounter builder per log file (per character)
  const builders = args.logs.map(logPath => {
    // Per-file character: the filename (eqlog_<Name>_pq.proj.txt) is
    // authoritative. A single global --character override must NOT be smeared
    // across every log when tailing multiple files — doing so mislabeled every
    // watched log as the main (e.g. all "Hitya") AND made the chat parser treat
    // each alt's own "You say to your guild" line as the main, double-posting
    // guild chat under the wrong speaker. Use --character only as a fallback,
    // and only when there's a single log for it to describe.
    const fromName  = characterFromFilename(logPath);
    const character = fromName
      || (args.logs.length === 1 ? args.flags.character : null)
      || 'unknown';
    // Register this log in the dashboard's watched list. Seed lastSeen from
    // file mtime so the dashboard shows useful "ago" times immediately —
    // without this seed, every log shows '?' until a fresh line arrives,
    // which never happens for chars who aren't currently logged in.
    let initialLastSeen = null;
    try { initialLastSeen = fs.statSync(logPath).mtime.getTime(); } catch {}
    stats.watchedLogs.push({ character, logPath, lastSeen: initialLastSeen });
    return {
      logPath,
      character,
      builder: new EncounterBuilder({
        character,
        onFlush: payload => uploadEncounter(payload, { botUrl, token, dryRun }).catch(err =>
          console.warn(`[upload error] ${err.message}`)
        ),
      }),
    };
  });

  // Enable the dashboard if stdout is a TTY (terminal). When the agent runs
  // headless under the Windows scheduled task, stdout is redirected and we
  // fall back to the plain log-line output that's been there forever.
  if (process.stdout.isTTY && !args.flags.dryRun) {
    _dashboardEnabled = true;
    renderDashboard();
    setInterval(renderDashboard, 5000);
    setupKeypressHandler();
  }

  // Idle ticker — flushes encounters that have gone quiet, AND periodically
  // pushes the /who buffer to the server even without a combat encounter.
  // Without the who-only flush, /whois on Discord can't find recently-observed
  // characters until the parser next kills something.
  let _whoDataLastSize  = 0;
  let _whoDataLastFlush = 0;
  setInterval(() => {
    const now = Date.now();
    for (const b of builders) b.builder.tickIdle(now);

    // Who-only flush: 5-second debounce after the buffer grows. Sends an
    // empty-encounter payload (no boss_name, no events) with the full
    // whoData snapshot — the server merges it into state.whoData and
    // /whois starts seeing the new entries within ~5-10 seconds of /who.
    if (whoData.size > _whoDataLastSize && (now - _whoDataLastFlush) >= 5000) {
      _whoDataLastSize  = whoData.size;
      _whoDataLastFlush = now;
      const character  = builders[0]?.character || 'unknown';
      const iso        = new Date(now).toISOString();
      uploadEncounter({
        agent_version: AGENT_VERSION,
        character,
        encounter: {
          started_at: iso,
          ended_at:   iso,
          boss_name:  null,
          events:     [],
          who_data:   Array.from(whoData.values()).filter(_isRegistryWho),
        },
      }, { botUrl, token, dryRun }).catch(err => {
        if (!_dashboardEnabled) console.warn(`[who flush] ${err.message}`);
      });
    }
  }, 5000);

  // Backfill mode
  if (args.flags.since) {
    const since = new Date(args.flags.since);
    const until = args.flags.until ? new Date(args.flags.until) : new Date();
    console.log(`Backfilling window: ${since.toISOString()} → ${until.toISOString()}`);

    // Chat is filtered out by shouldKeep at the byte-level, so handle it
    // before the combat filter. Batches up to 500 then flushes.
    const chatBatch = [];
    const flushChat = async (force) => {
      if (chatBatch.length === 0) return;
      if (!force && chatBatch.length < 500) return;
      const batch = chatBatch.splice(0);
      await uploadHistoricalChat(batch, { botUrl, token, dryRun })
        .catch(err => console.warn(`[chat backfill] ${err.message}`));
    };

    for (const b of builders) {
      console.log(`[${b.character}] scanning ${b.logPath}`);
      await readWindow(b.logPath, since, until, line => {
        // Fun-event detection — mirrors the opt-in backfill path so a CLI
        // bulk replay captures the same guild-flavor counters (Peopleslayer
        // LD, Malthur provisions, Dragon Punch, Dirges, Feral Avatar, …).
        // The bot's (guild_id, event_type, caster, event_ts) upsert key
        // dedups re-runs and overlap with other agents who saw the same
        // line, so emitting freely from --since is safe.
        for (const evt of _collectFunEvents(line, b.character)) funEventBuffer.push(evt);
        // Faction hits + /con standing transitions — self-only lines; rides
        // the 5s relay flush to /api/agent/faction. Bot-side dedup makes
        // complete-log backfill crawls idempotent.
        const facEvt = parseFactionLine(line, b.character);
        if (facEvt) factionBuffer.push(facEvt);
        const conFacEvt = parseConsiderLine(line, b.character);
        if (conFacEvt) factionBuffer.push(conFacEvt);
        const pfEvt = parsePopFlagLine(line, b.character);
        if (pfEvt) popFlagBuffer.push(pfEvt);
        // Witnessed hails — coverage for raiders who don't run Mimic.
        const hailEvt = parseWitnessedHail(line, b.character);
        if (hailEvt) popFlagBuffer.push(hailEvt);
        // Observed buff landings on other players — same as opt-in path.
        // Almost always expired by the time --since runs, but the web
        // filters expired so this costs nothing and occasionally rescues
        // a still-active buff from a recent log replay.
        // ⚠ NO target_id STAMP HERE, and never add one. _provableTargetId
        // reads the LIVE Zeal gauge, but this line is being replayed out of
        // an old log — so a stamp would attach the spawn id of whatever the
        // user is targeting NOW to a landing from hours ago. It would fire
        // precisely when the names match, i.e. exactly the same-name case
        // the id exists to disambiguate, and the read side TRUSTS a present
        // id. A backfilled landing has no knowable spawn; null is the truth.
        const bcEvt = parseBuffLanding(line, b.character);
        if (bcEvt) buffCastBuffer.push(bcEvt);

        const chatMsg = parseChatLine(line, b.character);
        if (chatMsg) {
          chatBatch.push({ ...chatMsg, uploadedBy: b.character });
          noteLootFromChat(chatMsg);   // officer Loot panel — LIVE tail
          noteRezFromChat(chatMsg);    // needs-rez board — "REZ <name>" / "rezzing <name>"
          if (chatBatch.length >= 500) flushChat(true).catch(() => {});
          return;
        }
        if (!shouldKeep(line, dropPatterns, keepPatterns)) return;
        const ts = parseEqTimestamp(line);
        const ev = parseEvent(line, ts);
        if (ev) b.builder.add(ev);
      });
      b.builder.flush();
    }
    await flushChat(true).catch(() => {});
    // Drain the fun-event + buff-cast buffers. Watch mode lets the 5s
    // startChatRelay tick handle this; --since is one-shot and exits, so we
    // flush inline before the process returns. Otherwise everything we just
    // detected sits in-memory and never uploads.
    if (funEventBuffer.length > 0) {
      await uploadFunEvents(funEventBuffer.splice(0), _uploadOpts || { botUrl, token, dryRun }).catch(err =>
        console.warn(`[fun-event backfill] ${err.message}`));
    }
    if (factionBuffer.length > 0) {
      await uploadFaction(factionBuffer.splice(0), _uploadOpts || { botUrl, token, dryRun }).catch(err =>
        console.warn(`[faction backfill] ${err.message}`));
    }
    if (popFlagBuffer.length > 0) {
      await uploadPopFlags(popFlagBuffer.splice(0), _uploadOpts || { botUrl, token, dryRun }).catch(err =>
        console.warn(`[pop-flag backfill] ${err.message}`));
    }
    if (buffCastBuffer.length > 0) {
      await uploadBuffCasts(buffCastBuffer.splice(0), _uploadOpts || { botUrl, token, dryRun }).catch(err =>
        console.warn(`[buff-cast backfill] ${err.message}`));
    }
    console.log('Backfill complete.');
    return;
  }

  // Watch mode (default for live raids)
  if (args.flags.watch || (!args.flags.once && !args.flags.since)) {
    console.log(`[boot] wolfpack-logsync v${AGENT_VERSION} ready — watching ${builders.length} log file(s).`);
    startChatRelay();  // start the 5s guild/raid chat flush interval
    for (const b of builders) {
      const watched = stats.watchedLogs.find(w => w.logPath === b.logPath);
      // In-log NPC-hail character inference. EQ NPCs always address the
      // hailing player by name in their hail / greeting response:
      //   "An old man says, 'Hail, Dant!'"
      // That name is the authoritative character ID, regardless of what the
      // log file is named. Catches renamed backup files (eqlog_Dant3 →
      // Dant) without skipping anything. Only listens for the first hail per
      // log; once captured, the builder's character is promoted and we never
      // re-check on this log to avoid mis-attributing a /who response, a
      // pet, etc.
      //
      // SPEAKER MUST LOOK LIKE AN NPC, NOT A PLAYER. v2.5.26 used a loose
      // /[A-Z][^\[\]]+? says/ that matched OTHER PLAYERS' /say lines too —
      // e.g. "Foo says, 'Hail, Hitya!'" in Canopy's log would rename
      // Canopy's builder to Hitya and pollute castCounts['Hitya'] with
      // Canopy's druid spells. Restricting the speaker to:
      //   - "a/an <lowercase rest>"      (a frog, an old man)
      //   - "the <lowercase rest>"       (the village elder)
      //   - "<Capitalized> <Capitalized>" (Captain Yorla, Sir Robin)
      // Single-word Title-cased speakers (real player names) are excluded —
      // EQ NPCs that look like single Capitalized words DO exist (Nillipuss,
      // Vox), but their hail responses to a player still include the
      // player's name in the captured group, so the rename is correct in
      // those cases too as long as the speaker isn't a friendly player.
      const HAIL_RE = /\]\s+(a\s+[a-z][^\[\]]*?|an\s+[a-z][^\[\]]*?|the\s+[a-z][^\[\]]*?|[A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)\s+says,?\s*['"](?:Hail|Greetings|Welcome|Well met),?\s+([A-Z][a-z]+)[!,.\s]/i;
      // #176 — a hail RESPONSE is broadcast to every nearby player, so a bystander's
      // log ALSO sees "<npc> says, 'Hail, Hitya!'". Pre-fix, that rebound the
      // bystander's builder to "Hitya" and relayed THEIR tells/chat/parses under
      // Hitya — a live cross-user privacy leak (2026-07-24, Sanctus Seru). Fix:
      // accept the rename ONLY when this log actually initiated the hail — it
      // emitted "You say, 'Hail, <npc>'" within the window AND the responding npc
      // is the one we hailed. A bystander never says "You say, 'Hail'", so their
      // log is no longer captured. (Speaker is now capture group 1, name group 2.)
      const SELF_HAIL_RE = /\]\s+You say,?\s*['"]Hail,?\s+(.+?)['"]\s*$/i;
      const _normHailNpc = (s) => String(s || '').toLowerCase().replace(/^(an?|the)\s+/, '').replace(/[!.,\s]+$/, '').trim();
      const HAIL_SELF_WINDOW_MS = 8000;
      let _hailFound = false;
      let _pendingSelfHail = null;   // #176 { target, atMs } — set on OUR own hail
      await tailFile(b.logPath, line => {
        if (watched) { watched.lastSeen = Date.now(); }
        // #176 — record OUR outgoing hail so a matching npc response can be trusted
        // as addressed to US (a bystander never emits "You say, 'Hail'").
        if (!_hailFound && line.indexOf('You say') !== -1) {
          const _sh = SELF_HAIL_RE.exec(line);
          if (_sh && _sh[1]) _pendingSelfHail = { target: _normHailNpc(_sh[1]), atMs: Date.now() };
        }
        if (!_hailFound) {
          const m = HAIL_RE.exec(line);
          if (m) {
            const speaker   = m[1];
            const inLogName = m[2];
            // The whole regex carries /i (so "an old man" / "Welcome" match
            // regardless of case), which ALSO lets the name group [A-Z][a-z]+
            // match a lowercase English word — "the captain says, 'Welcome to
            // Qeynos!'" captured "to" and renamed the builder to "To". Real EQ
            // hails address the player with a genuinely capitalized name
            // ("Hail, Dant!"), so re-validate the capture CASE-SENSITIVELY and
            // run it through the plausible-attacker guard. If it's junk we do
            // NOT latch _hailFound — keep listening for a later, valid hail.
            // #176 — AND require a matching self-hail: we must have just hailed
            // the very npc now responding. No self-hail (bystander) or a
            // different npc → ignore, don't latch, keep listening.
            const _now = Date.now();
            const selfHailed = !!_pendingSelfHail
              && (_now - _pendingSelfHail.atMs) <= HAIL_SELF_WINDOW_MS
              && _normHailNpc(speaker) === _pendingSelfHail.target;
            const validHailName = selfHailed && inLogName && /^[A-Z][a-z]+$/.test(inLogName) && isPlausibleAttacker(inLogName);
            if (validHailName) { _hailFound = true; _pendingSelfHail = null; }
            if (validHailName && inLogName !== b.character) {
              console.log(`[mimic] log "${path.basename(b.logPath)}" filename says ${b.character}, self-hailed ${speaker} → ${inLogName} — using ${inLogName}`);
              const old = b.character;
              b.character = inLogName;
              b.builder.character = inLogName;
              if (watched) watched.character = inLogName;
              try { confirmPlayer(inLogName); } catch {}
              try {
                stats.canonicalCharacter = stats.canonicalCharacter || {};
                stats.canonicalCharacter[old] = inLogName;
              } catch {}
              // Recalibrate: drop the OLD key's accumulated session-stats so
              // the renamed-from data doesn't continue to appear under the
              // new label. The user explicitly asked for "create a new entry
              // for the active character" semantics on rename.
              try { if (stats.castCounts && stats.castCounts[old])  delete stats.castCounts[old]; } catch {}
              try { if (stats.sessionDeeps && stats.sessionDeeps[old]) delete stats.sessionDeeps[old]; } catch {}
              try { if (stats.sessionMends && stats.sessionMends[old]) delete stats.sessionMends[old]; } catch {}
            }
          }
        }

        // ── Item clicky detection ──────────────────────────────────────────
        // "Your <Item> begins to glow." fires for any equipped/inventory
        // clicky use (Robe of the Spring, Voice of the Serpent, Blood Orchid
        // Katana, etc). The underlying spell starts casting immediately
        // after, so we stash the item's cast time keyed by character and let
        // _bumpBardMelody pick it up when Zeal label 134 changes within
        // CLICKY_WINDOW_MS. Without this the overlay defaults to the bare
        // spell's cast time, which is wrong for any item that overrides it.
        {
          const m = line.match(/\]\s+Your\s+(.+?)\s+begins\s+to\s+(?:glow|sparkle|hum|smoke|burn)\b/i);
          if (m) {
            const itemName = m[1];
            const cat = _itemClickyByNameLower.get(itemName.toLowerCase());
            const castMs = (cat && typeof cat.casttime === 'number' && cat.casttime > 0) ? cat.casttime : null;
            if (b.character) {
              _pendingClickies.set(b.character.toLowerCase(),
                { itemName, castMs, atMs: Date.now() });
            }
          }
        }

        // ── Camp-out early handoff (#72 P3) ────────────────────────────────
        // "It will take you about 30 seconds to prepare your camp." — this
        // raider is ~30s from vanishing. Flag `_camping` and fire an IMMEDIATE
        // reporter heartbeat (camping:true, no 20s wait) so the bot demotes us
        // from EVERY election ~30s before the 60s TTL would notice the logout,
        // handing chat/buffs/roster to a live groupmate while we're still here.
        // "You abandon your preparations to camp." (moved/cancelled) clears it.
        // Machine-level (one client = one camp) and NOT gated on exclusion — the
        // handoff is about liveness, not data. Patterns kept loose to survive
        // the guild-hall / "5 seconds" variants.
        if (/prepare your camp/i.test(line)) {
          if (!_camping) {
            _camping = true;
            console.log('[reporter] /camp detected → camping (early handoff started)');
            try { _reporterHeartbeatOnce(); } catch { /* best-effort — next 20s cycle catches it */ }
          }
        } else if (/abandon your preparations to camp/i.test(line)) {
          if (_camping) {
            _camping = false;
            console.log('[reporter] camp abandoned → resuming as election candidate');
            try { _reporterHeartbeatOnce(); } catch { /* best-effort */ }
          }
        }

        // ── Special relay lines: checked BEFORE the combat filter ──────────
        // These are NOT combat events and won't pass shouldKeep(), but we
        // still want to capture and relay them to Discord — UNLESS the owner
        // has set exclude_from_stats on the source character. Each push
        // below short-circuits on the prefs gate so an excluded character
        // generates zero outbound traffic from this machine.
        const _sourceExcluded = !shouldUploadForCharacter(b.character);

        // /tell handling — MUST be checked BEFORE shouldKeep because the byte-
        // level drop list filters out "tells you" / "you told" so neither the
        // local panel nor the upload path would otherwise see them.
        //
        // Two consumers, two gates:
        //   • LOCAL ring buffer (recentTells) — populated whenever parseTellLine
        //     matches on a non-excluded source. Powers the Mimic dashboard's
        //     "Recent Tells" card so a user can review tells without leaving
        //     the parser, even when they haven't opted into uploading.
        //   • UPLOAD buffer — gated on the per-character tell_relay opt-in
        //     flag (default off). Only opted-in characters reach Discord
        //     DM / wolfpack.quest/me/tells.
        // exclude_from_stats short-circuits both — an excluded character
        // generates zero tell traffic of any kind from this machine.
        const _tellPrefs = stats.characterPrefs && stats.characterPrefs[String(b.character || '').toLowerCase()];
        if (!_sourceExcluded) {
          const tellEvt = parseTellLine(line, b.character);
          if (tellEvt) {
            _pushRecentTell(tellEvt, b.character);
            if (_tellPrefs?.tell_relay) {
              tellBuffer.push({ ...tellEvt, character: b.character });
            }
            // Don't `return` — tells are side-channel. Continue so any further
            // processing (e.g. log highlighter, future panels) still sees the line.
          }
        }

        // /sll lockout output → bot timer (Available entries silently skipped)
        const lockoutEntry = parseSllLine(line);
        if (lockoutEntry) {
          if (!_sourceExcluded) _lockoutBuffer.push({ ...lockoutEntry, character: b.character });
          return;
        }
        // Even if parseSllLine returned null we may have toggled _inLockoutSection;
        // only bail early if we're inside a lockout block (line was consumed).
        if (_inLockoutSection && /^\[.+?\]\s+==/i.test(line)) return;

        // Druzzil Ro instance-kill announcement → boss timer + raid channel.
        // These server-god broadcasts are byte-identical across every log on
        // the box that received them, so a raw-text fingerprint dedups the
        // main-vs-alt double cleanly.
        const druzzilKill = parseDruzzilKill(line);
        if (druzzilKill) {
          const _dkFp = 'druzzil|' + line.replace(/^\[.+?\]\s*/, '').toLowerCase().replace(/\s+/g, ' ').trim();
          if (!_sourceExcluded && !_crossLogDupe(_dkFp)) druzzilKillBuffer.push(druzzilKill);
          return;
        }

        // PVP Druzzil Ro broadcast → PVP channel (with howl/backup logic in bot).
        // Same cross-log dedup — this is the "Wabumkin killed Qados posted
        // twice" fix at the source.
        const pvpBcast = parsePvpBroadcast(line);
        if (pvpBcast) {
          const _pvpFp = 'pvp|' + line.replace(/^\[.+?\]\s*/, '').toLowerCase().replace(/\s+/g, ' ').trim();
          if (!_sourceExcluded && !_crossLogDupe(_pvpFp)) {
            pvpBuffer.push(pvpBcast);

            // Hate-zone boss kills also fan out to the Supabase-backed
            // hate_kills tracker via /api/agent/hatekill. Own-guild kills
            // get a spot-picker post in the hate thread; foreign-guild
            // kills (including the (Instanced) ones we used to silently
            // drop pre-2026-06-21) land as unassigned rows for later web
            // inference assignment.
            const hk = _pvpBcastToHateKill(pvpBcast);
            if (hk) hateKillBuffer.push(hk);

            // Assist correlation: if the uploader was damaging this victim in
            // the last 30s AND the killing blow was someone else (or an NPC),
            // emit an assist row. cross-log dedup also applies — the same
            // assist won't post twice when multiple of our logs witness the
            // same death of someone we'd been swinging at.
            try {
              const assist = b.builder && b.builder._checkPvpAssist
                ? b.builder._checkPvpAssist(pvpBcast, { source: 'live_agent' })
                : null;
              if (assist) {
                const _aFp = 'assist|' + (assist.assister || '').toLowerCase() + '|' + _pvpFp;
                if (!_crossLogDupe(_aFp)) pvpAssistBuffer.push(assist);
              }
            } catch (e) { void e; }
          }
          return;
        }
        // No pattern matched — if it still looks like a kill broadcast, capture
        // the raw line for diagnosis (guildless/novel boss-kill phrasings).
        if (!_sourceExcluded) captureUnmatchedPvpKill(line);

        // Fun-event detection — shared gated dispatcher (_collectFunEvents):
        // one toLowerCase + substring gates instead of every detector's
        // regexes per line. Don't `return` after a match — fun events are
        // pure side-channel logging; the line still feeds other parsers.
        if (!_sourceExcluded) {
          for (const evt of _collectFunEvents(line, b.character)) funEventBuffer.push(evt);
        }
        // Faction hits + /con standing transitions — self-only lines; rides
        // the 5s relay flush to /api/agent/faction. Honors the per-character
        // exclude_from_stats opt-out like every other upload stream.
        const facEvt = parseFactionLine(line, b.character);
        if (facEvt && !_sourceExcluded) factionBuffer.push(facEvt);
        const conFacEvt = parseConsiderLine(line, b.character);
        if (conFacEvt && !_sourceExcluded) factionBuffer.push(conFacEvt);
        const pfEvt = parsePopFlagLine(line, b.character);
        if (pfEvt && !_sourceExcluded) popFlagBuffer.push(pfEvt);

        // Observed buff landing on another player (fills coverage for raiders
        // not running the agent). Cross-log dedup so a buff seen in main + alt
        // logs of one install isn't double-counted; the bot dedups across
        // separate installs by (target, spell, cast_at).
        // Track our own casts so a landing can be named from what WE cast
        // (authoritative — disambiguates shared landing messages + catches
        // spells the tracked-buff index doesn't carry).
        // One parse feeds both: noteSelfCast returns the parsed cast, and the
        // relay reuses it instead of re-running the identical regex.
        if (!_sourceExcluded) {
          const selfCast = noteSelfCast(line, b.character);
          // Relay our own cast → bot, so anyone targeting the same mob/player
          // sees it in Mob Info's Casting section (cross-client; only our
          // casts nameable).
          if (selfCast) relaySelfCastForCasting(line, b.character, selfCast);
          // A DI cast that gets interrupted/fizzles never consumed its recast.
          noteDiInterrupt(line, b.character);
          // Same for a silent pacify: it was stamped at cast begin because no
          // landing line exists, so an interrupt/fizzle/resist is the only
          // chance to take the timer back before someone trusts it.
          notePacifyMiss(line, b.character);
          // A CURE that fizzles/gets interrupted never landed — void the cure
          // the relay above just registered, so the bot doesn't retire a
          // debuff the raider is still carrying.
          noteCureCastFailed(line, b.character);
        }
        // Blind landings / fades (Pitted Iron Ring + generic NPC blind) —
        // drives the Mimic Blind Mode auto-pop in v1.1.8. Cheap regex set,
        // always runs (no _sourceExcluded gate — blindness is a UI thing,
        // not stat data we'd ever want suppressed).
        noteBlindLine(line, b.character);
        // PBAOE song mob counter (melody overlay swarm badge) — same UI-only
        // reasoning as blindness; exits on a Map miss for non-melody chars.
        noteSongAoeLine(line, b.character);
        // Public CH landings ("X is completely healed.") → heal-attribution ring.
        if (!_sourceExcluded) noteHealLandLine(line);
        // Other players' cast-starts → recipient-side heal attribution ring.
        if (!_sourceExcluded) noteCasterStart(line);
        // "Your pet's <X> spell has worn off." → drop it from the pet's buffs.
        if (!_sourceExcluded) notePetBuffWornOff(line, b.character);
        // Prefer the cast-correlated resolution (our own cast); fall back to the
        // tracked-buff index match for buffs we only witnessed as a bystander.
        const bcEvt = (!_sourceExcluded ? resolveSelfCastLanding(line, b.character) : null)
                   || parseBuffLanding(line, b.character);
        if (bcEvt && !_sourceExcluded) {
          // Which spawn did this land on? Provable only when this observer was
          // targeting it (see _provableTargetId). Stamped BEFORE the upload push
          // below so the local map and buff_casts carry the same answer.
          bcEvt.target_id = _provableTargetId(b.character, bcEvt.target);
          const _bcFp = `buffcast|${bcEvt.target}|${bcEvt.spell_id}|${bcEvt.landing_text}|${bcEvt.cast_at}`;
          // #154 — don't upload instant/uncatalogued self-cast nukes to
          // buff_casts: they carry no debuff timer and the cross-client
          // target-buffs relay would replay them onto every client's Mob Info +
          // Extended Target as a timer-less "fell off" entry. Same predicate the
          // LOCAL recordTargetBuffLanding drop uses, applied at the source so the
          // relay path is closed too. Real catalogued DoTs/curses still upload.
          if (!_shouldSuppressBuffLanding(bcEvt) && !_crossLogDupe(_bcFp)) buffCastBuffer.push(bcEvt);
          // If the buff landed on one of OUR pets, stamp it for the Pet tracker's
          // countdown (catalog duration anchored to this land). Local UI only.
          recordPetBuffLanding(bcEvt);
          // Also stamp it under the target name so Mob Info can show buffs on
          // whatever we're targeting (mob or player).
          recordTargetBuffLanding(bcEvt);
          // #105 — a slow landing on the current fight target → slow_on timeline
          // tick. Self-cast path: the caster is this log's character.
          try { b.builder.noteSlowLanding(bcEvt, b.character); } catch (e) { void e; }
          // #130 — module-level slow tracker (best-active-slow display + land
          // callout). Caster is known only for a genuine self-cast; a witnessed
          // beneficial-buff landing (parseBuffLanding) is not ours to attribute.
          try { _noteSlowForTarget(bcEvt, bcEvt._selfCast ? b.character : null); } catch (e) { void e; }
        }
        // Detrimental debuff landed by SOMEONE ELSE (bystander view) — Tash/Malo
        // on the boss, a slow/poison on a raider. Our OWN debuffs are already
        // resolved above (resolveSelfCastLanding) and beneficial buffs by
        // parseBuffLanding, so this only fires when neither produced an event.
        if (!_sourceExcluded && !bcEvt) {
          // #181 — ambiguous slow-family emote ("<mob> yawns." / "<mob> slows
          // down.") names no spell, so parseDebuffLanding can't refresh the
          // tracker. Refresh (only) an existing tracked slow of that family on
          // the mob it names — kills the false "Slow dropped" under a live
          // re-slow. Refresh-only: never creates an entry.
          if (line.endsWith('yawns.') || line.endsWith('slows down.')) {
            const _sm = line.match(/\]\s+(.+?)\s+(?:yawns|slows down)\.\s*$/);
            if (_sm && _sm[1]) {
              const _slowTs = parseEqTimestamp(line);   // tsMs is not in this callback's scope — derive from the line
              try { _refreshSlowFromAmbiguousLand(_sm[1], line, _slowTs ? _slowTs.getTime() : Date.now()); } catch (e) { void e; }
            }
          }
          const dbEvt = parseDebuffLanding(line, b.character);
          if (dbEvt && dbEvt.spell_name) {
            dbEvt.target_id = _provableTargetId(b.character, dbEvt.target);
            // Local Target Info — show the debuff on whatever's targeted (mob or
            // player), timed from the land. This is the emote-based path, so it
            // does NOT depend on a Zeal target-name match (the caster-self-cast
            // path does, and that breaks on instanced mob names like
            // "#Diabo_Xi_Va_Temariel" vs the emote's "Diabo Xi Va Temariel").
            recordTargetBuffLanding(dbEvt);
            // #105 — bystander-observed slow on the fight target → slow_on tick
            // (the caster is unknown from a landing line, so it's unattributed).
            try { b.builder.noteSlowLanding(dbEvt, null); } catch (e) { void e; }
            // #130 — module-level slow tracker; bystander land, caster unknown.
            try { _noteSlowForTarget(dbEvt, null); } catch (e) { void e; }
            // Upload BOTH mob and player debuffs so the bot's target-buffs relay
            // shows them cross-client — everyone targeting the boss sees
            // Tash/Malo/Turgur's even if they didn't personally witness the land
            // — and the cure queue still gets raider debuffs (Shadow Poison on
            // Malthur). The bot upserts by (target, spell, cast_at), so every
            // observer of the SAME land collapses to one row — no flood.
            const _dbFp = `buffcast|${dbEvt.target}|${dbEvt.spell_id}|${dbEvt.landing_text}|${dbEvt.cast_at}`;
            if (!_crossLogDupe(_dbFp)) buffCastBuffer.push(dbEvt);
          }
          // #206 — the THIRD capture path. Only lines neither timed path
          // claimed reach it, which is the whole point: an INSTANT effect has
          // no duration, so it is structurally unindexable above and
          // shouldKeep (default-DROP, and still ahead of us in this callback)
          // would have thrown it away. Local ring only — nothing uploads.
          if (!dbEvt) {
            try { noteMechanicLanding(line, b.character, b.builder); } catch (e) { void e; }
          }
        }

        // Server-wide PvP earthquake announcement → register the next-quake
        // time so the bot can show a countdown above the PvP timers (Discord +
        // web). Visible to everyone in zone; the bot dedups across agents.
        if (!_sourceExcluded) {
          const quakeEvt = parseEarthquake(line);
          if (quakeEvt && quakeEvt.next_quake_at !== _lastQuakeSig) {
            _lastQuakeSig = quakeEvt.next_quake_at;
            enqueueUpload('quake', { agent_version: AGENT_VERSION, quake: quakeEvt });
          }
        }
        // CH chain rotation — cleric "00N - CH - <target>" + "GO GO GO"
        // callouts in shout/raid chat. Local-only (zone-visible lines);
        // feeds the Mimic CH Chain overlay via /api/state.chChain.
        if (!_sourceExcluded) { try { trackChChainLine(line, b.character); } catch {} }
        // "<Cleric>'s casting is interrupted!" / "Your spell is interrupted." →
        // freeze that slot's cast bar and put a ✕ on it. No-ops unless a chain
        // is already running and the name maps to a slot mid-cast.
        if (!_sourceExcluded) { try { trackChChainInterrupt(line, b.character); } catch {} }
        // "<Tank> has been rescued by divine intervention!" → nominate the two
        // clerics who could put the next DI up (#204). Ungated on purpose —
        // local callout, no upload (see trackDiFired).
        // ⚠ MUST stay ABOVE the shouldKeep gate below: the death-save line does
        // not survive the byte filter (same trap as the "you have taken"
        // family). Moving it down silences the callout with no error anywhere;
        // test/di-callout.test.js pins that.
        try { trackDiFired(line); } catch {}
        // Raid-wide DA/invuln broadcast + healer mana roster — same
        // shout/raid/guild-chat macro pattern as CH chain, feeding the
        // Command Center overlay.
        if (!_sourceExcluded) { try { trackDaBroadcastLine(line, b.character); } catch {} }
        if (!_sourceExcluded) { try { trackDefensiveDiscLine(line, b.character); } catch {} }
        if (!_sourceExcluded) { try { trackHealerManaLine(line, b.character); } catch {} }
        // Self-only discipline reuse timer -> Command Center.
        if (!_sourceExcluded) { try { trackDisciplineTimerLine(line, b.character); } catch {} }
        // /random rolls + the loot-link roll-number convention — feeds the
        // Command Center Rolls card + the dashboard roll table. Local-only.
        if (!_sourceExcluded) { try { trackRollLine(line, b.character); trackRollItemLine(line); } catch {} }
        // #91 "You have looted" — the looter's own log is the only truth for
        // who ends up with no-drop loot. Live tail only (the 30-min upload gate
        // in uploadLooted keeps --since backfill from re-posting old loots).
        if (!_sourceExcluded) { try { trackLootedLine(line, b.character); } catch {} }
        // Auto-Raid Invite lead — raid-leader + ARI-enabled self-lines → the
        // bot auto-sets /autoraidinvite to this character. Live tail only.
        if (!_sourceExcluded) { try { trackAriLeadLine(line, b.character); } catch {} }

        // /pet health output (Quarm: standalone HP line + bare buff names in the
        // owner's own log). Feeds the per-owner pet buff SET + HP. Pure local UI
        // — no upload, never leaves the machine.
        applyPetHealthLine(line, b.character);

        // Charm pet death → drop it from the tracker right away (don't wait out
        // the 5-min linger window). Pass the local character so "You have slain"
        // is correctly attributed for the killer-guard (we don't kill our own
        // pet — same-named different mob).
        checkCharmPetDeath(line, b.character);

        // #142 — a boss death clears that mob's countdown timers (tank-buster,
        // deathtouch) so no phantom "next in Xs" lingers on the corpse; and a
        // configured PRECURSOR death arms the boss spawn pre-warn (Blood of
        // Ssraeshza dies → 2:10 cycle, "Paladin DA NOW" at 2:00). Both key off the
        // same slain/death line. Local-only, live tail.
        try { _cancelTimersOnMobDeath(line); } catch { /* never let a bad line break the tail */ }
        // #205 — "<Name> dies." is the FEIGN emote (never a death; see
        // test/feign-death-not-a-death.test.js). Nothing else in the agent
        // records that a feign happened, and the group-HP death watcher needs
        // it: a knight who feigns must never be turned into a corpse by a
        // gauge reading zero. Raw-line hook, substring-gated like the two below.
        try { const _dfd = parseEqTimestamp(line); noteFeignEmoteLine(line, _dfd ? _dfd.getTime() : Date.now()); } catch { void 0; }
        try { const _dts = parseEqTimestamp(line); _checkBossSpawnChain(line, _dts ? _dts.getTime() : Date.now()); } catch { void 0; }
        // `/zeal version` output → what's actually LOADED in this client. Runs
        // on the raw line before any filter because none of the keep patterns
        // describe it, and it gates on a substring first so the cost on a
        // non-matching line is one indexOf.
        try { noteClientVersionLine(line, b.character); } catch { void 0; }
        // #194 tag channel — same raw-line hook, same reasoning. The line
        // itself stays dropped by the custom-channel privacy filter; only the
        // structured {tank, mob, hp} extract rides observed_tanks.
        try { noteTagChannelLine(line, b.character); } catch { void 0; }
        // Chat rate limit — the server REFUSING a tag broadcast looks exactly
        // like nobody tagging, except Zeal still drew the arrow. Substring gate
        // first, same as the hooks above.
        try { const _dtrl = parseEqTimestamp(line); noteRateLimitLine(line, _dtrl ? _dtrl.getTime() : Date.now()); } catch { void 0; }
        // #56 — a mob death closes one same-name serial track; on K→0 (the last
        // instance died) it clears that name's stale debuff/slow/HP buckets so the
        // next same-name mob starts clean (the debuff-bleed fix). Same trusted
        // death detection as the timer cancel above; engine never breaks the tail.
        try { const _dts56 = parseEqTimestamp(line); _mobTracksOnDeathLine(line, _dts56 ? _dts56.getTime() : Date.now()); } catch { void 0; }

        // /who block boundaries (header/footer) → demarcate the current /who run
        // for the /who overlay. Rows themselves are attributed in recordWhoEvent.
        applyWhoLine(line);

        // Guild / raid chat relay
        const chatMsg = parseChatLine(line, b.character);
        if (chatMsg) {
          // Self-form speaker is a filename guess — after a character swap the
          // client keeps writing the OLD character's log, so ask Zeal (which
          // knows the client's real character) before trusting it. See
          // _resolveSelfChatSpeaker.
          if (chatMsg.speaker_source === 'log_name') {
            const resolved = _resolveSelfChatSpeaker(b.character);
            if (resolved && resolved.toLowerCase() !== String(chatMsg.speaker || '').toLowerCase()) {
              const w = whoData.get(resolved.toLowerCase()) || null;
              console.log(`[chat] self line in ${b.character}'s log, but ${b.character} isn't a live Zeal character — re-attributed to ${resolved}`);
              chatMsg.speaker = resolved;
              chatMsg.who = w ? { name: w.name, level: w.level, race: w.race, class: w.class } : null;
              chatMsg.speaker_source = 'zeal';
            }
          }
          // Anyone speaking in guild/raid chat is, by definition, a player —
          // add to the whitelist so their incoming damage / deaths show up on
          // the Tank dashboard (NPCs never use /gu or /rs).
          confirmPlayer(chatMsg.speaker);
          // Officer Loot panel — LIVE tail (speaker fully resolved by now).
          // Dedupes against the other live loop within 10 min, so being hooked
          // in both places is safe (this one is the primary relay path).
          noteLootFromChat(chatMsg);
          // #107 loot-post TTS + auction countdown chip. LIVE tail only — the
          // --since backfill path deliberately does NOT call this, so replaying
          // an old log never narrates stale loot or spawns phantom chips.
          noteLootAuction(chatMsg);
          // Cross-log arbitration: same channel + normalized text within 90s =
          // the same message captured from this person's main + alt logs
          // (self-form in one, bystander-form in the others). The speaker is
          // excluded from the fingerprint since the two forms can resolve to
          // different names — and when they DO disagree, the in-line
          // (third-person) name is server truth and upgrades a buffered
          // filename-guessed copy in place. See _chatCrossLogArbitrate.
          const _chatFp = `chat|${chatMsg.channel}|${String(chatMsg.text).toLowerCase().replace(/\s+/g, ' ').trim()}`;
          if (!_sourceExcluded && !_chatCrossLogArbitrate(_chatFp, chatMsg)) chatBuffer.push(chatMsg);
          return;
        }

        const ts = parseEqTimestamp(line);
        // Officer-tuned + personal triggers — evaluate BEFORE the combat filter
        // so keep-list MISSES (ENRAGED, snared, mesmerized, fizzles, cures…)
        // still fire; triggerVisibleLine() drops only the privacy/public-chat/
        // system lines so nothing private ever reaches a trigger. Cheap:
        // precompiled regex set; usually < 50 entries, < 50µs each.
        if (triggerVisibleLine(line, dropPatterns)) {
          try { evaluateTriggersAgainstLine(line, ts ? ts.getTime() : Date.now()); } catch {}
        }
        // Callout-replay (#98): capture raid-wide events that aren't combat
        // events (ENRAGE) — dropped before parseEvent — onto the fight timeline.
        try { b.builder.noteRaidLine(line, ts ? ts.getTime() : Date.now()); } catch {}

        // #36 AoE-dance callouts (DPS OUT / DPS IN + countdown). Runs on the
        // RAW line BEFORE shouldKeep — PBAE land messages ("flesh begins to
        // liquefy", "skin begins to rot") match no keep pattern, so they'd be
        // dropped before parseEvent ever sees them. Same watch-tail hook as
        // _checkTankBuster, same try/catch isolation; gated on the active boss.
        try { _checkAoeDance(line, ts ? ts.getTime() : Date.now()); } catch { void 0; }

        // ── Normal combat filter (gates parse + upload only) ────────────────
        if (!shouldKeep(line, dropPatterns, keepPatterns)) return;
        const ev = parseEvent(line, ts);
        if (ev) {
          // #142 — tank-buster detection off the ~4000 non-melee damage line
          // (Rage of Ssraeshza, spell 2310). Fires "TANK BUSTER" + (re)arms the
          // 60s cadence countdown. Local-only, live tail; keyed off the boss +
          // amount, so no dependency on the imported (non-firing) text trigger.
          try { _checkTankBuster(ev, line, ts ? ts.getTime() : Date.now()); } catch { void 0; }
          // Damage-taken audio alert — opt-in, default OFF, cooldown-limited.
          // Live tail only (backfill/--once never reach this loop), and it
          // takes WALL CLOCK rather than the log stamp: see the note on
          // _maybeAnnounceDamageTaken.
          try { _maybeAnnounceDamageTaken(ev, b.character, Date.now()); } catch { void 0; }
          // Pet combat observation — if the attacker is one of our pets (Zeal
          // slot 16), accumulate skill / max / total / hit-count stats for the
          // Pet tracker. Side-channel; doesn't touch the encounter builder.
          try { recordPetCombat(ev, b.character); } catch {}
          b.builder.add(ev);
        }
      });
    }
    // Run forever; intervals keep us alive
    return;
  }

  // One-shot mode (--once): read what's currently at end and exit
  if (args.flags.once) {
    console.log('One-shot mode: reading existing tail and exiting');
    // Simplest impl: act like watch but exit after 5 seconds of silence
    let idleCount = 0;
    for (const b of builders) {
      tailFile(b.logPath, line => {
        if (!shouldKeep(line, dropPatterns, keepPatterns)) return;
        const ts = parseEqTimestamp(line);
        const ev = parseEvent(line, ts);
        if (ev) { b.builder.add(ev); idleCount = 0; }
      });
    }
    // Log-size sweep (Ashieron's feedback): every 10 min, archive any watched
    // log over the size cap that has been idle long enough. First pass after
    // 2 min so an oversized log from a previous session is handled promptly.
    setTimeout(() => { _logRotateSweep().catch(() => {}); }, 2 * 60_000);
    setInterval(() => { _logRotateSweep().catch(() => {}); }, 10 * 60_000);
    setInterval(() => {
      idleCount++;
      if (idleCount > 10) {  // ~5s idle
        for (const b of builders) b.builder.flush();
        process.exit(0);
      }
    }, 500);
  }
}

// Export internals for tests; only run main() when invoked directly as CLI.
module.exports = {
  AGENT_VERSION,
  parseEvent, shouldKeep, parseEqTimestamp,
  DEFAULT_DROP_PATTERNS, KEEP_PATTERNS,
  buildFeedbackLogSlice, _feedbackLineAllowed,
  _noteBuffDurationsFromState, buffDurationStats, buffDurationTable, _noteBuffDurationSample,
  buffDurationFactorFor,
  SOURCELESS_SPELLS, BARD_SONGS,
  EncounterBuilder, characterFromFilename, isBackupLogFile, _splitBackupSuffix,
  trackChChainLine, chChainSnapshot, removeChChainSlot,
  _parseSntpReply,
  // Roll-call item labels — pure parser, tested against real captured chat.
  parseRollItemLine, _cleanRollItemCandidate, ROLL_ITEM_LINK_MS,
  _recordFightHistory, _fightHistoryForTest: () => stats.fightHistory,
  _resetFightHistoryForTest: () => { stats.fightHistory = []; },
  // CH cast bar / interrupt ✕ / DDR grade — exported for the scratchpad harness.
  trackChChainInterrupt, _chGradeForDelta, _chExpectedNextAt,
  CH_CAST_MS, CH_INTERRUPT_SLACK_MS, CH_INTERRUPT_LINGER_MS,
  CH_DDR_PERFECT_MS, CH_DDR_GREAT_MS, CH_DDR_GOOD_MS,
  CH_DDR_MARVELOUS_STREAK, CH_DDR_MIN_BEATS, CH_DDR_DISPLAY_MS,
  _setChDdrEnabledForTest: (v) => { _chDdrEnabled = !!v; },
  _resetChChainForTest: () => { _chChain = null; _lastChGoNum = null; },
  // #204 DI two-cleric callout — exported for the scratchpad harness.
  trackDiFired, diCalloutSnapshot, diCalloutCandidates, _diRankCandidates,
  _diSlotTurnInMs, _DI_FIRED_RX, DI_CALLOUT_NAMES, DI_CALLOUT_TTL_MS,
  _resetDiCalloutForTest: () => { _diCallout = null; _lastDiFired = { key: null, atMs: 0 }; },
  _readZipEntry, _parseCrashReason, _crashZipTime,
  // #107/#149 loot-post announce — exported for the scratchpad smoke test.
  parseLootChatBody, noteLootAuction, _parseAuctionDuration, _spokenDuration,
  _lootChipLabel, _activeTimers, _activeOverlays, _optinState, _lootAuctions,
  _lootAuctionsSnapshot,
  _consumeLootPosted,   // #149 loot-posted broadcast consumer
  noteLootFromChat,     // passive Loot Capture panel (untouched by #149)
  _getLootCursorForTest: () => _lastLootPostedId,
  _resetLootCursorForTest: () => { _lastLootPostedId = 0; _seenLootPostedIds = new Set(); },
  _lootCapturesForTest: () => _lootCaptures.slice(),
  // #108 loot bidding — exported for the scratchpad smoke test / harness.
  startWebDashboard,
  _loadBidFamily, _saveBidFamily, _bidFamilyNames, _opendkpAuthed,
  _loadPlannedBids, _savePlannedBids, _setPlannedBid,
  _pickAccountDkp,   // #124 — standings → pooled account balance (pure)
  _setBidFamilyForTest: (f) => { _bidFamily = f; },
  _setOpendkpAuthForTest: (a) => { _opendkpAuth = a; },
  _getBidFamilyForTest: () => _bidFamily,
  _getPlannedBidsForTest: () => _plannedBids,
  // #101 log-replay — exported for the scratchpad fixture.
  startReplay, stopReplay, _replayEvaluateLine, _liveFightActive,
  _fireLog, _triggerJournal, _triggerLastFire,
  // #142 buster/spawn-chain timers — exported for the scratchpad fixture.
  _startTimer, _activeTimersSnapshot, _cancelTimersOnMobDeath, _deadMobNameFromLine,
  // #207 callout dismissals — exported for the scratchpad fixture.
  _recordCalloutFeedback, _calloutFeedbackSnapshot, _flushCalloutVotes,
  // Age + liveness (2026-08-10) — exported so the wrapper is tested against
  // the shipped code rather than a copy.
  _noteDeath, _clearDeath, _isDead, _deadNamesSnapshot, _ageOfServerStamp,
  // #205 group-HP death watcher — the independent death source feeding that
  // registry. Exported so the tests exercise the shipped code, not a copy.
  _noteGroupHpFromState, _groupHpObservations, _groupDeathWatchSnapshot,
  noteFeignEmoteLine, _feignedRecently,
  _nowOnServerClock, _resolveHpValuesForName, _mtLiveStateByName,
  noteClientVersionLine, clientVersionsSnapshot,
  _checkBossSpawnChain, _checkTankBuster, _armBossCountdown, BOSS_SPAWN_CHAINS,
  _checkAoeDance, AOE_DANCE,   // #36 AoE-dance callouts — exported for the scratchpad fixture
  // Damage-taken audio alert — exported for the cooldown / default-off harness.
  _maybeAnnounceDamageTaken, _damageTakenBySelf, _setDamageAlert,
  DAMAGE_ALERT_COOLDOWN_MS,
  _damageAlertEnabledForTest: () => _damageAlertEnabled,
  evaluateTriggersAgainstLine, SLOW_SPELLS, _isSlowSpell,
  // #136 raid callout allow-list — exported for the scratchpad fixture.
  _fireTriggerActions, _calloutAllowedToSpeak, _calloutScopeGated, _CALLOUT_ALLOW_CATEGORIES,
  _setCurrentBossForTest: (name) => { stats.currentEncounterThreat = name ? { bossName: name } : null; },
  _getReplayStateForTest: () => _replayStateForWeb(),
  _setPersonalTriggersForTest: (arr) => { _personalTriggers = arr; },
  _setWatchedLogsForTest: (arr) => { stats.watchedLogs = arr; },
  _uploadQueueLenForTest: () => _uploadQueue.length,
};

if (require.main === module) {
  main().catch(err => { console.error('FATAL:', err); process.exit(1); });
}
